INSERT INTO `#__ra_organisations` (`id`, `record_type`, `code`, `nation_id`, `cluster`, `name`, `details`, `website`, `co_url`, `latitude`, `longitude`, `logo`, `logo_align`, `email_header`, `colour_header`, `colour_body`, `colour_footer`, `welcome_letter`, `reminder_letter`) VALUES
(1, 'G', 'AV01', 1, '', 'Bristol Group', 'The Bristol Group has about 800 members and arranges about 300 walks each year. Walks range from full day rambles across the Brecon Beacons to short walks in the city and the surrounding countryside.', 'https://bristolramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/bristol-group', '51.452651040000', '-2.770587293310', '', 'right', NULL, 'rgba(155, 200, 171, 0.5)', 'rgba(155, 200, 171, 0.1)', 'rgba(155, 200, 171, 1)', '', ''),
(2, 'G', 'AV02', NULL, NULL, 'Somer Valley Group', 'Somer Valley Ramblers walk most Sundays and also the first and third Wednesday of each month.  The Sunday walks vary in length and are usually within a forty miles radius of Midsomer Norton/ Radstock area.  The Wednesday walks are usually between ...', 'https://www.somervalleyramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/somer-valley-group', '51.329209800000', '-2.562701486570', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(3, 'G', 'AV03', NULL, NULL, 'Southwold (Yate) Group', 'Like the outdoors, the changing seasons, walking in areas of outstanding natural beauty. So do we – at Southwold (Yate) Ramblers. We are at the southern end of the Cotswolds. Come and try us.', 'https://www.ramblers.org.uk/southwold', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/southwold-yate-group', '51.553919050000', '-2.399151603823', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(4, 'G', 'AV04', NULL, NULL, 'Bath Group', 'We organise regular group walks in the beautiful countryside around Bath. ', 'https://www.bathramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/bath-group', '51.374498730000', '-2.414620678763', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(5, 'G', 'AV05', NULL, NULL, 'Severnside Group', 'Our Group is based in Bradley Stoke, north Bristol. Ideally sited for access to the Cotswolds, Mendips, Wiltshire Downs, Wye Valley and Brecon Beacons.', 'https://www.severnside-ramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/severnside-group', '51.588716790000', '-2.576815975656', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(6, 'G', 'AV07', NULL, NULL, 'Kingswood Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.kingswoodramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/kingswood-group', '51.462003560000', '-2.416244086093', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(7, 'G', 'AV08', NULL, NULL, 'Clevedon Group', 'Clevedon Ramblers Group love the outdoors, walking not only local walks but the Mendips, Quantocks Cotswolds and parts of Wales, and areas of outstanding beauty.\r\nNew walkers are always welcome.', 'https://clevedonramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/clevedon-group', '51.427864400000', '-2.747901970603', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(8, 'G', 'AV50', NULL, NULL, 'Brunel Walking & Activity Group', 'A group for walkers based in the Bristol & Bath area. Brunel has two sub-groups: one for walkers in their 20s & 30s and a second aimed at those in their 40s & 50s with busy working lives.', 'https://www.brunelwalking.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/brunel-walking-activity-group', '51.461495820000', '-2.567575348461', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(9, 'G', 'BF01', NULL, NULL, 'North Bedfordshire Group', 'We are a friendly group and each Saturday afternoon we have a walk that is between 5-7 miles. Once or twice a month, we also have a morning walk starting at 10.00am distance of 10-12 miles. ', 'https://www.ramblers.org.uk/north-bedfordshire', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/north-bedfordshire-group', '52.124867000000', '-0.450233977404', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(10, 'G', 'BF03', NULL, NULL, 'Leighton Buzzard Group', 'Leighton Buzzard Ramblers are a friendly and sociable group. We have a programme of walks every Sunday and mid-week walks too. We also organise holidays and social events.', 'https://lb-ramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/leighton-buzzard-group', '51.943846820000', '-0.600240614833', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(11, 'G', 'BF04', NULL, NULL, 'Ivel Valley Group', 'Bedfordshire\'s largest and most active walking group. Walks every Sunday and Wednesday, every second Tuesday and Thursday and most Fridays. Evening walks in the summer.', 'https://www.ivelvalleywalkers.co.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/ivel-valley-group', '52.068517670000', '-0.317133556820', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(12, 'G', 'BF06', NULL, NULL, 'Lea & Icknield (Luton) Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.ramblers.org.uk/lea-icknield', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/lea-icknield-luton-group', '51.914505290000', '-0.457298623308', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(13, 'G', 'BK01', NULL, NULL, 'East Berkshire Group', 'As well as a regular programme of walks, publishes local walks guides, organises coach-connected walks, long distance walks in stages, and city walks.', 'https://www.eastberksramblers.org', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/east-berkshire-group', '51.509067620000', '-0.756738088049', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(14, 'G', 'BK02', NULL, NULL, 'Mid Berkshire Group', 'All are welcome on our walks - you need to bring a packed lunch etc for walks more than 5 miles. Parking tends to be roadside or in car parks.', 'https://www.mbra.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/mid-berkshire-group', '51.415551200000', '-1.086347549464', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(15, 'G', 'BK03', NULL, NULL, 'West Berkshire Group', 'The Group welcomes all comers and offers a choice of around four led walks each week, most of which are in West Berkshire and the surrounding areas.  It also does volunteer footpath maintenance work.', 'https://www.wberksramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/west-berkshire-group', '51.456354490000', '-1.396135977256', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(16, 'G', 'BK04', NULL, NULL, 'South East Berks Group', 'We are a very friendly walking group based in the Bracknell, Ascot, Crowthorne and Sandhurst areas offering around 4 walks each week catering for all ages and abilities.\r\n', 'https://sebr.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/south-east-berks-group', '51.408130680000', '-0.739708765921', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(17, 'G', 'BK05', NULL, NULL, 'Pang Valley Group', 'Welcome. Our friendly walking group is based in the countryside around Reading. Our varied walks are mainly 4-5 miles - some longer, a few shorter. We mainly walk at the weekend with some Wednesdays.', 'https://www.pvramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/pang-valley-group', '51.479640630000', '-1.148501705877', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(18, 'G', 'BK06', NULL, NULL, 'Loddon Valley Group', 'Loddon Valley Ramblers help the people around the Wokingham Borough enjoy a variety of regular walks around the beautiful countryside of Berkshire, Hampshire and the Chilterns. . ', 'https://www.lvra.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/loddon-valley-group', '51.429447780000', '-0.883820060784', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(19, 'G', 'BK07', NULL, NULL, 'Windsor & District Group', 'The Windsor and District Ramblers is a UK walking group for people of all ages living in East Berkshire.  We are a small and friendly bunch who welcomes other walkers to join us on any of our walks. ', 'https://www.ramblers.org.uk/windsor-district', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/windsor-district-group', '51.467054880000', '-0.604469436458', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(20, 'S', 'BK40', NULL, NULL, 'Berkshire Weekend Walkers Group', 'The Berkshire Weekend Walkers is primarily intended for people of a working age, but welcomes anyone that can get out for a walk at the weekend.\r\nWe lead walks all over Berkshire and occasionally venture into the neighbouring counties. We also ...', 'https://www.berksww.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/berkshire-weekend-walkers-group', '51.450375410000', '-1.102642619256', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(21, 'S', 'BK50', NULL, NULL, 'Berkshire Walkers Group', 'The Berkshire Walkers is a Ramblers \'Young Persons\' Group aimed at people in their 20s and 30s.\r\nWe have a healthy membership mainly in Berkshire with walks often attracting over 20 people. \r\n', 'https://www.berkshirewalkers.co.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/berkshire-walkers-group', '51.450375410000', '-1.042642619256', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(22, 'G', 'BU01', NULL, NULL, 'Amersham & District Group', 'We are a friendly and welcoming walking group conveniently located in the heart of the Chiltern Hills.  We welcome walkers of all ages and offer a variety of walks on most days of the week.', 'https://amershamramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/amersham-district-group', '51.664515410000', '-0.621941228197', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(23, 'G', 'BU03', NULL, NULL, 'Aylesbury & District Group', 'We provide walks to suit everyone. Tuesday walks are about 4 miles, no faster than 2 miles per hour average.  Thursday walks are 6 - 9 miles and somewhat faster.  Sunday walks can be up to 14 miles', 'https://www.aylesbury-ramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/aylesbury-district-group', '51.833676330000', '-0.864504061831', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(24, 'G', 'BU04', NULL, NULL, 'Hillingdon Group', 'We walk in the Chilterns and our local area, but also further afield and in London. We have short, easy walks on Sat mornings, longer walks Sat afternoons & all day walks on Weds & Sun. \r\n', 'https://hillingdonramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/hillingdon-group', '51.542510450000', '-0.470561201216', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(25, 'G', 'BU05', NULL, NULL, 'Milton Keynes & District Group', 'The Milton Keynes Ramblers group organises at least one walk per week. We walk mainly in North Bucks, Northamptonshire and Bedfordshire, but also go further afield for weekends away.', 'https://www.mkramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/milton-keynes-district-group', '52.026123860000', '-0.832498356673', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(26, 'G', 'BU06', NULL, NULL, 'North West London Group', 'Norrth West London Ramblers Group helps local people enjoy walking and protect the places we all love to walk. We organise day walks in the countryside around London every Sunday.', 'https://www.ramblers.org.uk/north-west-london', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/north-west-london-group', '51.579658560000', '-0.307395347652', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(27, 'G', 'BU09', NULL, NULL, 'Wycombe District Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.wycomberamblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/wycombe-district-group', '51.636395080000', '-0.791514417156', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(28, 'S', 'BU40', NULL, NULL, 'Chilterns Weekend Walkers Group', 'Regular weekend walks in the Chiltern Hills together with an active social calendar have made the Chilterns Weekend Walkers a very popular walking group affiliated to the Ramblers Association.', 'https://www.chilternsww.co.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/chilterns-weekend-walkers-group', '51.743095940000', '-0.737433395820', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(29, 'S', 'BU50', NULL, NULL, 'Hike MK Group', 'We are Hike MK - a walking group for younger adults of the Milton Keynes & North Buckinghamshire area.', 'https://hikemk.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/hike-mk-group', '52.025997860000', '-0.832632300583', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(30, 'S', 'BU51', NULL, NULL, 'Chiltern Young Walkers Group', 'A friendly and sociable walking group aimed at people in their 20s and 30s who enjoy a large variety of walks and social events every weekend across the Chilterns', 'https://www.chilterns2030s.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/chiltern-young-walkers-group', '51.684933400000', '-0.692094447487', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(31, 'G', 'CB01', NULL, NULL, 'Cambridge Group', 'Cambridge group welcomes people of all ages who enjoy walking and the countryside. Our walks are in Cambridgeshire and neighbouring counties. We normally walk on most Saturdays and many Mondays.', 'https://cambridgeramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/cambridge-group', '52.243254120000', '0.169972809335', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(32, 'G', 'CB02', NULL, NULL, 'Huntingdonshire Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://huntsramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/huntingdonshire-group', '52.373731830000', '-0.220771094968', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(33, 'G', 'CB03', NULL, NULL, 'Peterborough Group', 'Our groups help local people enjoy walking, both exploring and protecting the varied countryside around Peterborough. This encompasses areas in Rutland, Northamptonshire, Leicestershire, Lincolnshire,', 'https://peterboroughramblers.co.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/peterborough-group', '52.608523030000', '-0.253091763442', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(34, 'G', 'CB04', NULL, NULL, 'Fenland Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://fenlandramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/fenland-group', '52.562931740000', '0.060811881517', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(35, 'S', 'CB50', NULL, NULL, 'Peterborough Younger Walkers Group', 'We are a friendly bunch of people who enjoy walking. We cater for people from Peterborough and the surrounding area (Cambridgeshire, South Lincolnshire and North and East Northamptonshire).  \r\n\r\nWe meet up every two weeks throughout the year and ...', 'https://www.pyw.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/peterborough-younger-walkers-group', '52.608515770000', '-0.253186627959', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(36, 'S', 'CB51', NULL, NULL, 'Walk Cambridge Group', 'We are an active walking and social group, aimed at people in their 20s, 30s & 40s living in or near Cambridge. The group offers a varied programme of walks across Cambridgeshire and surrounding areas', 'https://www.walkcambridge.org/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/walk-cambridge-group', '52.339855030000', '0.033318134750', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(37, 'G', 'CE01', 0, 'WA', 'Aberystwyth Group', 'The Aberystwyth Group of the Ramblers operates in the northern half of Ceredigion in Mid Wales. It is part of the nationwide Ramblers organisation which represents the interests of walkers throughout ', 'https://aberystwythramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/aberystwyth-group', '52.374053600000', '-3.932675194574', '', 'right', NULL, 'rgba(155, 200, 171, 0.5)', 'rgba(155, 200, 171, 0.1)', 'rgba(155, 200, 171, 1)', '', ''),
(38, 'G', 'CE02', NULL, NULL, 'Cardigan & District Group', 'We are the Cardigan & District group of Ramblers located in Mid Wales.\r\n\r\nWalkers attend the walks at their own risk.\r\nNo liability can be accepted by The Ramblers ...', 'https://www.cardiganramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/cardigan-district-group', '52.100710120000', '-4.441232201751', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(39, 'G', 'CE03', NULL, NULL, 'Lampeter Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.ramblers.org.uk/lampeter', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/lampeter-group', '52.173697340000', '-4.052814608062', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(40, 'G', 'CH01', NULL, NULL, 'Congleton Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.congletonramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/congleton-group', '53.162229720000', '-2.285695976363', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(41, 'G', 'CH02', NULL, NULL, 'East Cheshire Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://ramblerseastcheshire.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/east-cheshire-group', '53.274935380000', '-2.136961939940', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(42, 'G', 'CH03', NULL, NULL, 'South Cheshire Group', 'SOUTH CHESHIRE RAMBLERS\r\n\r\nWe are a friendly and sociable group of people, from all walks of life who all have one thing in common - a love of walking.\r\n', 'https://www.ramblerssouthcheshire.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/south-cheshire-group', '53.063214980000', '-2.530477894368', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(43, 'G', 'CL02', NULL, NULL, 'Camel District (Wadebridge) Group', 'The Camel group of the Rambler\'s Association covers the beautiful Camel estuary, rugged moorlands, hidden valleys and attractive villages. From breathtaking views along the coastal fringes to the atmospheric Cornish rainforest North Cornwall has it ...', 'https://www.ramblers.org.uk/camel-district-wadebri', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/camel-district-wadebridge-group', '50.626102860000', '-4.612187705857', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(44, 'G', 'CL03', NULL, NULL, 'Caradon Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.ramblers.org.uk/caradon', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/caradon-group', '50.439717210000', '-4.426208123868', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(45, 'G', 'CL04', NULL, NULL, 'Carrick Group', 'Carrick takes its name from the stretch of water known as the Carrick Roads, into which the rivers Percuil, Penryn and Fal flow.  Our walking area extends from the north to the south coasts of .....', 'https://www.facebook.com/CornwallRamblers/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/carrick-group', '50.276591170000', '-5.052456651178', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(46, 'G', 'CL07', NULL, NULL, 'Restormel Group', 'Restormel Group is situated in the centre of Cornwall with superb coastal walks from Fowey to Portholland.  Our diverse area also includes the Eden Project, Heligan Gardens, Nature Reserves and ...', 'https://www.ramblers.org.uk/cornwall', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/restormel-group', '50.375948810000', '-4.854382959730', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(47, 'G', 'CL08', NULL, NULL, 'West Cornwall (Penwith & Kerrier) Group', 'Penwith and Kerrier cover the west of Cornwall from Portreath on the north-west coast, west to Land’s End, easterly along the south coast, around the Lizard peninsula and up to and including ...', 'https://www.facebook.com/groups/958828250851602/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/west-cornwall-penwith-kerrier-group', '50.125227940000', '-5.374829024058', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(48, 'S', 'CL51', NULL, NULL, 'Kernow Boots Group', 'Kernow  Boots is a Young Cornwall Ramblers walking group mainly aimed at  20-30s.  As well as exploring Cornwall on regular weekend walks, we organise social events and the occasional weekend away ...', 'https://www.facebook.com/Kernowboots/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/kernow-boots-group', '50.441115000000', '-4.748750000000', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(49, 'G', 'DE01', NULL, NULL, 'Amber Valley Group', 'Amber Valley Group was formed in 1976, based in mid-Derbyshire.\r\nWe now have 200+ members, from a variety of backgrounds, and age groups, but with a common love of the countyside.\r\nWhy not join us in some of our ...', 'https://www.ambervalleyramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/amber-valley-group', '53.029259010000', '-1.466620949462', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(50, 'G', 'DE02', NULL, NULL, 'Derby & S Derbyshire Group', 'Derby and South Derbyshire group was formed in 1976. We walk mainly in Derbyshire but also in Staffordshire, Cheshire and Leicestershire.\r\n <b>Join us for a walk.</b> \r\n\r\nhttp://www.derbyramblers.org.uk', 'https://www.derbyramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/derby-s-derbyshire-group', '52.846347270000', '-1.542409796201', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(51, 'G', 'DE03', NULL, NULL, 'Erewash District Group', 'Erewash group help people enjoy walking and protect the places we all love to walk. We organise regular walks led by local people – a great way to get outside and make new friends.', 'https://www.erewashramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/erewash-district-group', '52.935503150000', '-1.346734128562', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(52, 'G', 'DE04', NULL, NULL, 'Derbyshire Dales Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.derbyshiredalesramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/derbyshire-dales-group', '53.128464600000', '-1.693635982044', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(53, 'G', 'DN01', NULL, NULL, 'East Devon Group', 'We\'re an enthusiastic and friendly group, offering the choice of 6 walks a week ranging from a half-day stroll to a full-day hike. New members and visitors are welcome, why not come and give us a try?', 'https://www.ramblers.org.uk/east-devon', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/east-devon-group', '50.764312180000', '-3.195323086703', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(54, 'G', 'DN02', NULL, NULL, 'Exeter & District Group', 'Our regular walks take place on a Sunday and range in length from 8 to 11 miles, with short walks on Saturdays.  We also have shorter walks during the week that usually finish with a sociable pub lunch, providing the opportunity to meet with friends ...', 'https://www.exeterramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/exeter-district-group', '50.738165560000', '-3.545465176271', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(55, 'G', 'DN03', NULL, NULL, 'Moorland Group', 'Every Sunday we offer a strenuous walk of ten to fifteen miles mostly over the rough and rugged terrain of Dartmoor.  We are a friendly and welcoming group of people and we are dog friendly.', 'https://moorlandramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/moorland-group', '50.643677500000', '-3.875118477580', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(56, 'G', 'DN05', NULL, NULL, 'North Devon Group', 'The walks offered by by our Group are varied in distance and varied in the days we walk on. We offer some evening walks in the Spring and Summer.', 'https://www.northdevonramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/north-devon-group', '50.999642330000', '-4.108808332165', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(57, 'G', 'DN07', NULL, NULL, 'Plymouth Group', 'We are a friendly group who cater for walkers with varying requirements,  from those who like to take all day to do 5 miles to those who want to get lots of miles under their belt as quickly as possible. We have  regular walks on Sundays and ...', 'https://www.plymouthramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/plymouth-group', '50.414763600000', '-4.024979518220', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(58, 'G', 'DN08', NULL, NULL, 'South Devon Group', 'The South Devon Group of the Ramblers is a very friendly collection of individuals who welcome other walkers to join us on any of our walks. We walk every Thursday for 6-8 miles, and every Sunday for 9-12 miles, as well as the first Tuesday of every ...', 'https://www.southdevonramblers.com', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/south-devon-group', '50.488673410000', '-3.615242258046', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(59, 'G', 'DN09', NULL, NULL, 'South Hams Group', 'We are the South Hams Group with easy access to coastal paths, Dartmoor National Park and the South Hams countryside in between. Walking Tuesday, Thursday and Sunday with a list of 600 possible walks.', 'https://www.ramblers.org.uk/south-hams', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/south-hams-group', '50.306967600000', '-3.752286527277', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(60, 'G', 'DN10', NULL, NULL, 'Tavistock Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.tavistockramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/tavistock-group', '50.671688260000', '-4.148408512710', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(61, 'G', 'DN11', NULL, NULL, 'Tiverton Group', '', 'https://www.facebook.com/groups/438399116311261', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/tiverton-group', '50.891652600000', '-3.627057351256', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(62, 'G', 'DN13', NULL, NULL, 'Totnes Group', 'Do come and join us for one of our walks. We can\'t promise to take you to Narnia, but you can be sure of an excellent day\'s walking in convivial company. Visitors and new members are most welcome.', 'https://www.ramblers.org.uk/totnes', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/totnes-group', '50.446420850000', '-3.770924033102', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(63, 'G', 'DN16', NULL, NULL, 'Teignmouth & Dawlish Group', 'We are a small Group based in the twin sea side towns of Teignmouth & Dawlish in South Devon. Everyone is welcome to join us on a walk.', 'https://teignramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/teignmouth-dawlish-group', '50.597112810000', '-3.547864837509', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(64, 'S', 'DN51', NULL, NULL, 'Devon Bootlegs Group', 'A warm welcome from the Devon Bootlegs. The Bootlegs have over 100 members\r\nfrom all over Devon. For Sunday walks we meet at 9:30 am, Bude Street, Exeter\r\n(behind the bus station) to arrange car sharing, unless otherwise stated. Please come and join ...', 'https://www.devonbootlegs.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/devon-bootlegs-group', '50.751094360000', '-3.780076959920', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(65, 'G', 'DT01', NULL, NULL, 'East Dorset Group', 'We provide led walks from many different locations, varying in length from 5 miles to over 15 miles.  Members receive a printed programme three times a year.', 'https://www.eastdorsetramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/east-dorset-group', '50.761210650000', '-2.023131422673', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(66, 'G', 'DT02', NULL, NULL, 'South Dorset Group', 'You are very welcome on our walks as a \'taster\', or if you belong to another Ramblers Group, If you want to bring your dog with you, please contact the Walk Leader first.', 'https://sdgmembers.weebly.com/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/south-dorset-group', '50.725407190000', '-2.458201683078', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(67, 'G', 'DT03', NULL, NULL, 'North Dorset Group', 'We aim to provide two walks each week, ranging in distance between 6 and 12 miles, on Wednesdays and Sundays.', 'https://www.ramblers.org.uk/north-dorset', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/north-dorset-group', '50.911457450000', '-2.315829660723', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(68, 'G', 'DT04', NULL, NULL, 'West Dorset Group', 'Walking with our group gives you the opportunity to enjoy the beautiful, unspoilt coastline and countryside of West Dorset, as well as the camaraderie of a friendly group of people. ', 'https://www.westdorsetramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/west-dorset-group', '50.784686260000', '-2.752239571876', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(69, 'S', 'DT50', NULL, NULL, 'Dorset Young Walkers Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://dorsetyoungwalkers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/dorset-young-walkers-group', '50.802414010000', '-2.334308914329', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(70, 'S', 'DT51', NULL, NULL, 'Dorset 4050 Walkers Group', 'Despite our group name, we really don\'t care what age you are; if you like walking with a friendly, relaxed, easy going group of people, who occasionally socialize you\'re most welcome to join us.', 'https://www.ramblers.org.uk/dorset-4050-walkers', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/dorset-4050-walkers-group', '50.802414010000', '-2.274308914329', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(71, 'G', 'ER01', NULL, NULL, 'Beverley Group', 'Beverley Ramblers  - think of our historic town surrounded by acres of rolling countryside - an ideal walking environment.  Our led walks enable all ages and abilities to enjoy the benefits of walking', 'https://www.eastyorkshireramblers.org.uk/groups/be', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/beverley-group', '53.891445460000', '-0.468928561696', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(72, 'G', 'ER03', NULL, NULL, 'Hull & Holderness Group', 'Our Group\'s area stretches from Hull through the vast Holderness plain and then north on East Yorkshire\'s long coastline from spectacular Spurn Point to Bridlington.', 'https://www.eastyorkshireramblers.org.uk/groups/hu', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/hull-holderness-group', '53.834278970000', '-0.186215476028', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(73, 'G', 'ER04', NULL, NULL, 'Ryedale Group', 'Our geographical area takes in an exciting mixture of scenic countryside. Spoilt for choice, there is Vale of Pickering, Yorkshire Wolds, Howardian Hills and the North York Moors National Park.', 'https://www.eastyorkshireramblers.org.uk/groups/ry', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/ryedale-group', '54.176912060000', '-0.808912986820', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(74, 'G', 'ER05', NULL, NULL, 'Scarborough & District Group', 'Walkers in our Scarborough area are rewarded with varied countryside, good paths along the tops of soaring sea cliffs, dramatic heather moors of the national park, plus peaceful pastoral and woodland.', 'https://www.scarboroughramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/scarborough-district-group', '54.261292520000', '-0.456686169787', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(75, 'G', 'ER06', NULL, NULL, 'Pocklington Group', 'Pocklington is the Gateway to the outstanding Yorkshire Wolds. We help protect those places we love to walk. Locals and visitors are welcome to walk with us and feel the physical and social benefits.', 'https://www.eastyorkshireramblers.org.uk/groups/po', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/pocklington-group', '53.954246230000', '-0.682975088443', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(76, 'G', 'ER07', NULL, NULL, 'York Group', 'We organise a variety of walks across North  and East Yorkshire, in the Dales and to the coast. There is one to suit you, so join us and experience the benefits of walking.', 'https://yorkramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/york-group', '53.997962990000', '-1.103044178571', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(77, 'G', 'ER09', NULL, NULL, 'Howden & Goole Group', 'Although small we are a very friendly group and most of our walks are within a 30 minute drive from Howden and Goole.  Come & walk with us and make new friends', 'https://www.eastyorkshireramblers.org.uk/groups/ho', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/howden-goole-group', '53.735035940000', '-0.842496428552', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(78, 'S', 'ER50', NULL, NULL, 'East Yorks Get Your Boots On Group', 'Walking Group for people in their 20s and 30s. With membership based mainly in East Yorkshire & York we offer a varied programme covering North & East Yorks. With walks of different lengths and difficulty we have something to offer for everyone. We ...', 'https://www.gybo.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/east-yorks-get-your-boots-group', '54.029525030000', '-0.658919601775', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(79, 'G', 'ES01', NULL, NULL, 'Brentwood Group', 'Brentwood Ramblers have a walking programme of nearly 250 walks per year, consisting of:- \r\n\r\nDay walks on Sundays & Tuesdays (10 to 12 miles)\r\nMorning walks on Saturdays & Thursdays (5 to 6 miles)\r\n', 'https://brentwoodramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/brentwood-group', '51.638651760000', '0.310751020327', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(80, 'G', 'ES02', NULL, NULL, 'Colchester Group', 'The Group serves the Borough of Colchester. Our area stretches from beautiful Dedham Vale and Constable country in the north east to the yachting and wildlife havens of Mersea Island and the Colne estuary to the south. We organise walks across North ...', 'https://www.colchester-ramblers.co.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/colchester-group', '51.872579290000', '0.860863708625', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(81, 'G', 'ES03', NULL, NULL, 'South East Essex Group', 'Enjoy the countryside with your local Ramblers\' group. What better way is there to get to know your own area than to walk in the local countryside?\r\n\r\nWe look forward to walking with you.', 'https://www.ramblers.org.uk/south-east-essex', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/south-east-essex-group', '51.538042620000', '0.728698153428', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(82, 'G', 'ES04', NULL, NULL, 'Thurrock Group', 'Thurrock Ramblers lead group walks every Sunday and Wednesday evenings in the summer.', 'https://thurrockramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/thurrock-group', '51.505978180000', '0.373119535920', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(83, 'G', 'ES05', NULL, NULL, 'West Essex Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://west-essexramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/west-essex-group', '51.697113410000', '0.132194130175', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(84, 'G', 'ES06', NULL, NULL, 'Chelmer & Blackwater Group', '\r\nChelmer & Blackwater Group is centrally based in Chelmsford, Essex and our Leaders arrange over 200 walks annually. Prospective new members are always welcome.\r\n\r\n', 'https://www.chelmerandblackwater-ramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/chelmer-blackwater-group', '51.725479490000', '0.480852210429', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(85, 'G', 'ES07', NULL, NULL, 'Braintree & North Essex Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.northwestessexramblers.co.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/braintree-north-essex-group', '51.941941670000', '0.589887363523', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(86, 'G', 'ES08', NULL, NULL, 'Havering & East London Group', 'We walk regularly on Tuesday, Saturday and Sunday, in Essex and London with visits into Kent too. \r\nSometimes walks may be changed or even cancelled. Please check our website to confirm', 'https://www.haveringeastlondonramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/havering-east-london-group', '51.552005840000', '0.166189768516', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(87, 'G', 'ES09', NULL, NULL, 'Basildon Greenway Group', 'Basildon Greenway Ramblers lead weekly walks of 5 to 6 miles Tuesday mornings and 9 to 12 miles on Sundays around Essex and occasionally further afield.', 'https://www.greenwayramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/basildon-greenway-group', '51.590139250000', '0.466272246922', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(88, 'G', 'ES10', NULL, NULL, 'Tendring District Group', 'North East Essex from the River Stour and Suffolk border in the north to the coast and to the River Colne in the south, with the coast to the east and its inland boundary with Colchester to the west.', 'https://www.tendringramblers.co.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/tendring-district-group', '51.871437570000', '1.115047031763', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(89, 'G', 'ES11', NULL, NULL, 'Redbridge Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://redbridgeramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/redbridge-group', '51.585657610000', '0.075862754232', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(90, 'G', 'ES12', NULL, NULL, 'Rochford & Castle Point Group', 'The group covers the area in south-east Essex, to the north and west of Southend-on-Sea.\r\nMost walks are local with some in mid and north Essex and North Kent. We attempt to walk every Tuesday and at weekends.', 'https://www.facebook.com/rcpramblers/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/rochford-castle-point-group', '51.580679420000', '0.767689728150', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(91, 'G', 'ES14', NULL, NULL, 'Stort Valley Group', 'The Stort Valley Group of <i> The Ramblers </i> was formed in 1995, the current membership is about 80 strong. The group serves Harlow Town and the nearby towns and villages situated in the Stort Valley bordering Essex with Hertfordshire. \r\n\r\nOur ...', 'https://www.stortvalleyramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/stort-valley-group', '51.768348700000', '0.108542799761', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(92, 'G', 'ES15', NULL, NULL, 'Uttlesford Group', 'Uttlesford group was formed in1995. Centred on Uttlesford District Council (Saffron Walden) a small group organising walks of about 10 miles most Saturdays and a 5-6 mile walk in mid week. ', 'https://www.uttlesfordramblers.org/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/uttlesford-group', '51.934700720000', '0.279716289807', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(93, 'G', 'ES16', NULL, NULL, 'Maldon & Dengie Hundred Group', 'Maldon is an ancient but still active port situated where the Rivers Blackwater and Chelmer flow into the Blackwater Estuary.  The Dengie peninsula lies between the estuaries of the Crouch and Blackwater. It includes the largest, continuous area of ...', 'https://www.maldonanddengieramblers.org/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/maldon-dengie-hundred-group', '51.709720660000', '0.783137757461', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(94, 'S', 'ES52', NULL, NULL, 'Estuary Pramblers Group', 'Estuary Pramblers organises free, short sociable walks for families with babies in South Essex. ', 'https://www.ramblers.org.uk/essex-ramblers', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/estuary-pramblers-group', '51.777396000000', '0.556883000000', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(95, 'S', 'ES30', NULL, NULL, 'Essex Friends Group', 'Shorter walks at a slower pace across Essex.', 'https://www.ramblers.org.uk/essex-friends', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/essex-friends-group', '51.745633310000', '0.333190822197', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(96, 'S', 'ES31', NULL, NULL, 'East Essex Friends Group', 'Shorter walks over distances of 4 – 5 miles', 'https://www.eastessexfriends.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/east-essex-friends-group', '51.804884290000', '0.793096078083', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(97, 'S', 'ES32', NULL, NULL, 'Lea Valley Friends Group', 'Easy-paced walks of 6.5km/4 miles approx. (2 hours)  in  Essex countryside, Epping Forest, country parks, historic walks in London, walks through Royal parks and along Thames, Lea and canal towpaths. ', 'https://www.leavalleyfriends.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/lea-valley-friends-group', '51.702351670000', '0.130549438109', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(98, 'S', 'ES50', NULL, NULL, 'Hike Essex Group', 'Hike Essex is an established walking group for working age people. We have walks every weekend, as well as mid-week evening walks between Spring and Autumn, and regular weekends away and socials.', 'https://www.hikeessex.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/hike-essex-group', '51.769553270000', '0.574442783002', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(99, 'G', 'GR01', NULL, NULL, 'Cirencester Group', 'Cirencester is part of the Gloucestershire Area Ramblers covering the southeast of the county between Northleach, Tetbury, Stroud and Lechlade, although our walks regularly take us outside this area. ', 'https://cirencesterramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/cirencester-group', '51.742825650000', '-1.912136184845', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(100, 'G', 'GR02', NULL, NULL, 'Forest of Dean Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.fodramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/forest-dean-group', '51.828455240000', '-2.489787677246', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(101, 'G', 'GR03', NULL, NULL, 'South Cotswold Group', 'We walk in the very scenic South Cotswolds and Berkeley Vale and often further afield 2, 3 and even 4 times a week. If you like the idea of walking and making new friends do come along and try us out.', 'https://www.southcotswoldramblers.org.uk/wp/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/south-cotswold-group', '51.706462480000', '-2.266152952914', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(102, 'G', 'GR04', NULL, NULL, 'Gloucester Group', 'Walkers usually meet in Gloucester to share transport. Please note that dogs are not allowed on walks.', 'https://www.gloucester-ramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/gloucester-group', '51.859240950000', '-2.231468534845', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(103, 'G', 'GR05', NULL, NULL, 'Cleeve Group', 'We walk every Sunday and some Wednesdays within a 25 mile radius of Cheltenham. Come and join us for company, for health and for a day out in the countryside', 'https://www.ramblers.org.uk/cleeve', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/cleeve-group', '51.960890110000', '-2.041487380335', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(104, 'G', 'GR07', NULL, NULL, 'North Cotswold Group', 'A friendly Group that has been in existence for nearly 30 years and offers a varied and interesting programme of walks throughout the year. Walks are typically 6 - 10 miles at an easy pace. We welcome', 'https://www.ramblers.org.uk/north-cotswold', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/north-cotswold-group', '51.930761070000', '-1.784880169413', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(105, 'S', 'GR50', NULL, NULL, 'Gloucestershire Walking Group', 'This group is for walkers who want to walk outside of normal working hours. We offer walks most Sundays and on Thursday evenings during the summer. ', 'https://www.gwg.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/gloucestershire-walking-group', '51.825484490000', '-2.096301554577', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(106, 'G', 'HF01', NULL, NULL, 'West Herts Group', 'West Herts group is a friendly group of walkers who enjoy our countryside both locally and further afield. We walk regularly on Sundays, once a month on Tuesdays, have weekends away and social events.', 'https://westhertsramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/west-herts-group', '51.772803380000', '-0.411606593893', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(107, 'G', 'HF02', NULL, NULL, 'East Hertfordshire Group', 'We have been a Ramblers group for over 30 years, covering the east Hertfordshire area. Not only do we walk throughout Hertfordshire, but also into west Essex, south Cambridgeshire, ...................', 'https://www.easthertsramblers.co.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/east-hertfordshire-group', '51.848449110000', '-0.003261876914', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(108, 'G', 'HF03', NULL, NULL, 'North Hertfordshire Group', 'We are a friendly Group, encouraging not only walking, but related social events and holidays at home and abroad.  We walk every Sunday, most Saturdays and occasional mid week.', 'https://www.nhrg.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/north-hertfordshire-group', '51.921846090000', '-0.227865357995', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL);
INSERT INTO `#__ra_organisations` (`id`, `record_type`, `code`, `nation_id`, `cluster`, `name`, `details`, `website`, `co_url`, `latitude`, `longitude`, `logo`, `logo_align`, `email_header`, `colour_header`, `colour_body`, `colour_footer`, `welcome_letter`, `reminder_letter`) VALUES
(109, 'G', 'HF04', NULL, NULL, 'North London & South Herts Group', 'Most of our members live in Barnet, Enfield and Potters Bar. We lead a long and a short walk each weekend, usually in Hertfordshire or the Chilterns. We welcome walkers of all ages and experience.', 'https://www.hnmramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/north-london-south-herts-group', '51.658566880000', '-0.134809545880', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(110, 'G', 'HF05', NULL, NULL, 'Royston Group', 'A very nice group walking Tuesdays, Thursdays and Sundays', 'https://www.ramblers.org.uk/royston', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/royston-group', '52.010599140000', '-0.030198671991', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(111, 'G', 'HF06', NULL, NULL, 'Watford & Three Rivers Group', 'We are an active sociable group who put on walks every weekend usually on Saturdays and a shorter midweek walk once every three weeks or so. ', 'https://www.watfordand3riversramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/watford-three-rivers-group', '51.670311170000', '-0.396908792508', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(112, 'G', 'HF07', NULL, NULL, 'Finchley & Hornsey Group', 'The Finchley and Hornsey Ramblers Group is based in North London but we have such wonderful countryside around us that  we walk anywhere between the Chilterns in the West through to Essex in the East, not forgetting the captivating byways of London ...', 'https://www.ramblers.org.uk/finchley-hornsey', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/finchley-hornsey-group', '51.596792240000', '-0.181738070223', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(113, 'S', 'HF51', NULL, NULL, 'Herts Weekend Walkers Group', 'Herts Weekend Walkers leads varied walks in and around Hertfordshire aimed at people of working age in their 40s & 50s who can usually only find time to get out to enjoy a walk at the weekend.', 'https://www.hertsww.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/herts-weekend-walkers-group', '51.807940220000', '-0.178847817383', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(114, 'S', 'HF52', NULL, NULL, 'Stag Walkers Group', 'Stag Walkers is a Ramblers group aimed primarily at younger people in their 20s and 30s which offers a range of led walks and social events around Hertfordshire, Bedfordshire and south Cambridgeshire.', 'https://www.stagwalkers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/stag-walkers-group', '51.955712450000', '-0.192271612428', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(115, 'G', 'HW01', NULL, NULL, 'Leadon Vale Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.herefordshireramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/leadon-vale-group', '52.076000230000', '-2.456609894783', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(116, 'G', 'HW02', NULL, NULL, 'Ross-on-Wye Group', '', 'https://www.herefordshireramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/ross-wye-group', '51.916011370000', '-2.619944130613', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(117, 'G', 'HW04', NULL, NULL, 'Hereford Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.herefordshireramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/hereford-group', '52.074958640000', '-2.796219013001', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(118, 'G', 'HW07', NULL, NULL, 'Mortimer Group', 'If you enjoy walking and want to meet like-minded people, then Mortimer Ramblers welcome you to their friendly and sociable group. We have a walk programme to suit everyone.                       ', 'https://www.herefordshireramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/mortimer-group', '52.253062210000', '-2.831358712367', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(119, 'G', 'IL01', NULL, NULL, 'Blackheath Group', 'We offer friendly and invigorating walks through the stunning countryside surrounding London (particularly to the south) as well as popular shorter walks mainly in southeast London itself.', 'https://www.blackheathramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/blackheath-group', '51.463666830000', '0.024326725059', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(120, 'G', 'IL02', NULL, NULL, 'Hampstead Group', 'Our walks range from less than 4 to 16+ miles and take place throughout London and the Home Counties. Just turn up at the station from which the walk starts and you can be sure of a good welcome.', 'https://www.ramblers.org.uk/hampstead/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/hampstead-group', '51.547242400000', '-0.138300589802', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(121, 'G', 'IL03', NULL, NULL, 'South Bank Group', 'We\'re a friendly and varied group of people of all ages and interests who share a love of walking. Most of our members live in Lambeth or Southwark, but many come from further afield.', 'https://www.southbankramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/south-bank-group', '51.464515360000', '-0.095145857912', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(122, 'G', 'IL04', NULL, NULL, 'North East London Group', 'The North East London Ramblers Group is part of the Ramblers Association and has a membership of about four hundred from all ages and walks (pardon the pun) of life. The group aims to offer a Walk on each Saturday of the year except over Christmas.', 'https://www.nelr.co.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/north-east-london-group', '51.531547250000', '-0.051293538966', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(123, 'G', 'IL05', NULL, NULL, 'Hammersmith & Wandsworth Group', 'We are the Hammersmith, Fulham & Wandsworth Group of the Ramblers\' Association. As our name suggests, most of our members live in either the London Borough of Hammersmith and Fulham, or the London Borough of Wandsworth.\r\n\r\nMost of our walks are four ...', 'https://www.hfwramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/hammersmith-wandsworth-group', '51.466075990000', '-0.197529514143', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(124, 'G', 'IL06', NULL, NULL, 'Kensington, Chelsea & Westminster Group', 'Our members, united by a love of walking, have a wide range of ages, backgrounds and other interests.  We have a programme for almost every Saturday and some Sundays, some weekday walks and a weekend away most years. Weekends have been Swanage ...', 'https://www.kcwramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/kensington-chelsea-westminster-group', '51.509041030000', '-0.171893321002', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(125, 'G', 'IL08', NULL, NULL, 'West London Group', 'West London Ramblers are a friendly group of people of varied interests who  share a love of walking as a great way to get outside, improve health and happiness and make new friends. Our walks .....', 'https://www.westlondonramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/west-london-group', '51.495250080000', '-0.348731981259', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(126, 'S', 'IL40', NULL, NULL, 'London Strollers Group', 'The London Strollers are different as our led walks are usually based in the Greater London area, we walk are at a leisurely pace and our walks are usually between 2 and 7 miles.', 'https://www.londonstrollers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/london-strollers-group', '51.473919200000', '-0.087178367029', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(127, 'S', 'IL50', NULL, NULL, 'Metropolitan Walkers Group', 'The London-based walking group for people in their 20s and 30s. We walk in London and the South East and on weekend trips away. Six walks a week: short strolls to fast 20+ mile hikes over the hills.', 'https://www.metropolitan-walkers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/metropolitan-walkers-group', '51.503919200000', '-0.117178367029', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(128, 'S', 'IL51', NULL, NULL, 'Capital Walkers Group', 'Capital Walkers is a thriving walking group. The group is aimed at people aged 40+, it was set up by people who have walked on their own and with other groups for many years.', 'https://www.capitalwalkers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/capital-walkers-group', '51.488919200000', '-0.057178367029', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(129, 'G', 'IW01', NULL, NULL, 'Isle of Wight Group', 'The Walks Coordinator is Steve Gibson.  \r\nEmail stevegbsn@icloud.com\r\nPhone 07901 555789.\r\n\r\nThis page is for the Isle of Wight Group. This is the larger of the two Ramblers walking groups on the island. ', 'https://iowramblers.com', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/isle-wight-group', '50.675760370000', '-1.296571661211', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(130, 'S', 'IW50', NULL, NULL, 'Wight Sole Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.wightsole.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/wight-sole-group', '50.675951940000', '-1.266146028441', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(131, 'G', 'KT01', NULL, NULL, 'Ashford (Kent) Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.ashfordramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/ashford-kent-group', '51.216655270000', '0.812156954908', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(132, 'G', 'KT02', NULL, NULL, 'Maidstone Group', 'Maidstone group helps those who enjoy walking to explore the Kent countryside and beyond.  Our walk leaders provide an interesting and varied programme of walks throughout the year.  ', 'https://www.maidstoneramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/maidstone-group', '51.235009680000', '0.580585742690', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(133, 'G', 'KT03', NULL, NULL, 'North West Kent Group', 'We runs up to 3 walks on Wednesdays & usually 1 at week-end. We regularly stop for a pub lunch on our walks. We are involved in footpaths clearance. We run group holidays, map reading courses.', 'https://nwkramblers.chessck.co.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/north-west-kent-group', '51.460878430000', '0.142358913421', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(134, 'G', 'KT04', NULL, NULL, 'Tonbridge & Malling Group', 'On our Sunday and mid-week morning walks we explore the beautiful countryside within Tonbridge & Malling and surrounding areas.', 'https://tonbridgeandmallingramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/tonbridge-malling-group', '51.273636770000', '0.357920603282', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(135, 'G', 'KT05', NULL, NULL, 'Tunbridge Wells Group', 'Regardless of whether you are a member of the Ramblers or not, you are welcome to join the Tunbridge Wells Ramblers on a Sunday morning for a stroll enjoying the best that Kent and Sussex can off', 'https://www.ramblers.org.uk/tunbridge-wells', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/tunbridge-wells-group', '51.114381060000', '0.430678209119', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(136, 'G', 'KT06', NULL, NULL, 'Canterbury Group', 'The Cathedral City of Canterbury is a perfect centre for walking. Two long distance paths go through the city, the North Downs Way and the Stour Valley Walk and the Saxon Shore Way passes along the...', 'https://www.kentramblers.org.uk/canterbury/canterb', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/canterbury-group', '51.283884820000', '1.101624173765', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(137, 'G', 'KT07', NULL, NULL, 'Sevenoaks Group', 'Everyone is welcome to join us on our organised walks. Many members of other Ramblers groups walk with us, and non-members also come along - we hope that after 2 or 3 walks you\'ll want to join!\r\n', 'https://sevenoaksramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/sevenoaks-group', '51.275504470000', '0.172094694481', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(138, 'G', 'KT08', NULL, NULL, 'Medway Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://medwayramblers.weebly.com', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/medway-group', '51.425749890000', '0.569530279548', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(139, 'G', 'KT09', NULL, NULL, 'White Cliffs Group', 'Our Group walks between the flat lands of Thanet and the Romney Marsh, enjoying the Downland beside Dover and Folkestone and the Alkham and Elham Valleys.  Our programme includes easy walks in Thanet and longer treks and adventures across the ...', 'https://www.whitecliffsramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/white-cliffs-group', '51.160024960000', '1.161779163111', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(140, 'G', 'KT10', NULL, NULL, 'Bromley Group', 'We are a large, friendly and welcoming Group with the aim of offering a variety of at least four walks of different lengths each and every week.', 'https://www.bromleyramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/bromley-group', '51.371999080000', '0.051525778693', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(141, 'G', 'KT11', NULL, NULL, 'Dartford & Gravesham Group', 'The Dartford and Gravesham Group walk on Sundays, some weekdays and the occasional Saturday, usually within a 40-mile radius of the area. All are welcome to join us – just turn up! Walkers in any doubt whether the walk will take place should confirm by using the contact details.', 'https://www.kentramblers.org.uk/dartford/dartford-', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/dartford-gravesham-group', '51.416222880000', '0.335275022644', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(142, 'S', 'KT50', NULL, NULL, 'East Kent Walking Group', 'East Kent Walking Group appeals to people mainly in the 20s to 50s range, around the East Kent area. We are a friendly and welcoming group made up of couples and singles.', 'https://www.ekwg.co.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/east-kent-walking-group', '51.205521240000', '0.987300325235', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(143, 'S', 'KT51', NULL, NULL, 'West Kent Walking Group', 'We are an upbeat walking group ( typically 30s to 60s), and we provide a mixed programme of walks every weekend. We also organise social events, weekends away, plus other activities. ', 'https://www.westkentwalkinggroup.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/west-kent-walking-group', '51.287010230000', '0.375478142012', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(144, 'G', 'LD01', NULL, NULL, 'Furness Group', 'Furness Ramblers are a small friendly Group who organise walks in the Lake District and North Pennines  to suit walkers of all abilities.  We also work to monitor and protect the paths in our Area.', 'https://www.furnessramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/furness-group', '54.338364120000', '-3.262636441777', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(145, 'G', 'LD02', NULL, NULL, 'Grange over Sands Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.ramblers.org.uk/grange-over-sands', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/grange-over-sands-group', '54.197234540000', '-2.935616548438', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(146, 'G', 'LD03', NULL, NULL, 'Kendal Group', 'Welcome, we lead walks in and around the beautiful Lake District, protect our countryside and footpaths and publish walks booklets for the Kendal area. Join us on a walk we are a friendly crowd', 'https://kendalramblers.weebly.com/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/kendal-group', '54.349903880000', '-2.796611915864', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(147, 'G', 'LD04', NULL, NULL, 'Lancaster Group', 'Lancaster Group helps local people enjoy walking and protect the places we all love to walk. We walk in a wide area, including North Lancashire, Morecamble Bay, the Lake District and Yorkshire Dales.', 'https://www.lancasterramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/lancaster-group', '54.136669410000', '-2.640588965602', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(148, 'G', 'LD05', NULL, NULL, 'Penrith Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.ramblers.org.uk/penrith', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/penrith-group', '54.612928690000', '-2.622126287834', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(149, 'G', 'LD07', NULL, NULL, 'Carlisle Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.ramblers.org.uk/carlisle', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/carlisle-group', '54.827091200000', '-3.051894071414', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(150, 'S', 'LD50', NULL, NULL, 'Summit Good Group', 'We\'re a walking group in the Lake District aimed at younger walkers in their 20\'s and 30\'s. \r\n\r\n', 'https://www.summitgood.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/summit-good-group', '54.534803020000', '-2.865258107517', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(151, 'G', 'LE01', NULL, NULL, 'Hinckley Group', 'We are located in Leicestershire with Charnwood Forest, Bosworth Field, Bradgate Park all nearby . Further afield we also travel to the Cotswolds ,the Derbyshire Peak District and other counties.', 'https://hinckleyramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/hinckley-group', '52.616495490000', '-1.391027836255', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(152, 'G', 'LE02', NULL, NULL, 'Leicester & District Group', 'Leicester & District Group organises over 300 walks a year ranging from 4 to 15 mile walks.', 'https://www.ramblers-leicester.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/leicester-district-group', '52.594577390000', '-1.178466188504', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(153, 'G', 'LE03', NULL, NULL, 'Melton Mowbray Group', 'Varied walks organised each week throughout the year local to Melton Mowbray and further afield in the Peak District.  Walks to suit all ages including families with small children.  Long weekend walking breaks out of Melton Mowbray Area.\r\n\r\nActive ...', 'https://www.meltonramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/melton-mowbray-group', '52.796455860000', '-0.856147646148', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(154, 'G', 'LE04', NULL, NULL, 'Coalville Group', 'We are Coalville Ramblers, one of eight Groups which make up the Leicestershire and Rutland Area of the Ramblers Association. We are based in the former mining town of Coalville in North-west Leicest', 'https://www.facebook.com/groups/492625248899894', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/coalville-group', '52.753150790000', '-1.405008775502', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(155, 'G', 'LE05', NULL, NULL, 'Rutland Group', 'The Rutland Group organises a fortnightly programme of Sunday walks throughout the year.  The distance walked is generally 8-10 miles, with a morning coffee stop and picnic lunch.  ', 'https://www.ramblers.org.uk/rutland', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/rutland-group', '52.660752160000', '-0.654649351105', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(156, 'G', 'LE06', NULL, NULL, 'Loughborough & District Group', '', 'https://www.loughboroughramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/loughborough-district-group', '52.737014780000', '-1.146171831810', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(157, 'G', 'LE07', NULL, NULL, 'Lutterworth Group', 'The Lutterworth group are a friendly, welcoming group of keen walkers. We organise walks in the area and special walks out of area from time to time.', 'https://www.lutterworthramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/lutterworth-group', '52.539329660000', '-1.007891887126', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(158, 'S', 'LE50', NULL, NULL, 'Leicestershire & Rutland Walking Group', 'Welcome to the Leicestershire and Rutland Walking Group (LRWG). We\'re an active and friendly walking group originally aimed at people in their 20s, 30s and 40s. ', 'https://www.lrwg.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/leicestershire-rutland-walking-group', '52.665799070000', '-1.013161954472', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
