(210, 'G', 'NE07', NULL, NULL, 'Rushcliffe Group', 'The Rushcliffe Group is a large group with members varying in age from 40 somethings to the mature 70 year olds. We are based in the South of Nottinghamshire', 'https://www.rushclifferamblers.org', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/rushcliffe-group', '52.867906310000', '-1.133547527128', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(211, 'G', 'NE08', NULL, NULL, 'Broxtowe Group', 'We are an active group walking on Wednesdays and Sundays. We organise short and longer walks all year round in the Broxtowe area of Nottinghamshire and further afield. Everyone welcome!', 'https://www.broxtoweramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/broxtowe-group', '52.989091820000', '-1.269307218151', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(212, 'G', 'NE09', NULL, NULL, 'Gedling Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends ...', 'https://www.gedlingramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/gedling-group', '53.010833940000', '-1.089535446615', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(213, 'G', 'NE10', NULL, NULL, 'Mansfield & Sherwood Ramblers', 'Ramblers group for Mansfield, Warsop, Sutton-in-Ashfield, Kirkby-in-Ashfield, Edwinstowe and Ollerton areas of the county. Walks take place every Sunday with alternating short and long walks. ', 'https://www.mansfieldramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/mansfield-sherwood-ramblers', '53.160525430000', '-1.172758827263', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(214, 'G', 'NE11', NULL, NULL, 'Southwell Group', 'A small friendly Group based in around the Southwell area of Notts offering varied regular walks in and around the county. For more information please visit our web-site, www.southwellramblers.org.uk', 'https://www.southwellramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/southwell-group', '53.074158490000', '-0.987619676565', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(215, 'G', 'NE14', NULL, NULL, 'Collingham Group', 'Join our small and friendly group based around Collingham and East Nottinghamshire.', 'https://www.nottsarearamblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/collingham-group', '53.177900910000', '-0.746040253521', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(216, 'G', 'NE15', NULL, NULL, 'Vale of Belvoir Group', 'A small and friendly group covering the Notts Vale of Belvoir area. Our varied programme offers weekly Sunday and monthly Wednesday walks. In June and July we offer leisurely, mid-week strolls ', 'https://www.vbramblers.org/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/vale-belvoir-group', '52.925064660000', '-0.942171798606', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(217, 'S', 'NE50', NULL, NULL, 'Notts Derby Walking Group', 'NDWG is the RA Group specifically for people in their 20s, 30s and 40s. New members are always welcome. We offer a variety of walks from easier rambles to energetic mountain hikes.', 'https://ndwg.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/notts-derby-walking-group', '53.105301440000', '-1.028184259979', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(218, 'S', 'NE51', NULL, NULL, 'One Step Walkers Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends ...', 'https://www.onestepwalkers.co.uk/index.php', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/one-step-walkers-group', '53.135301440000', '-1.058184259979', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL);
INSERT INTO `#__ra_organisations` (`id`, `record_type`, `code`, `nation_id`, `cluster`, `name`, `details`, `website`, `co_url`, `latitude`, `longitude`, `logo`, `logo_align`, `email_header`, `colour_header`, `colour_body`, `colour_footer`, `welcome_letter`, `reminder_letter`) VALUES
(219, 'S', 'NE70', NULL, NULL, 'Robin Hood Way Group', 'Our groups helps people enjoy walking and protect the Robin Hood Way long distance recreational route through Nottinghamshire. It a 105 mile self guided route via a fully illustrated book.', 'https://www.robinhoodway.com', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/robin-hood-way-group', '53.146958000000', '-1.004393000000', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(220, 'G', 'NN01', NULL, NULL, 'Tyneside Group', 'All our walks are by coach from Newcastle on Sunday & Wednesday. For all walks, paste this link into your browser: http://www.ramblers.org.uk/go-walking/find-a-walk-or-route.aspx?group=NN01&tab=walks#', 'https://www.ramblers.org.uk/tyneside', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/tyneside-group', '55.016319220000', '-1.598264653222', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(221, 'G', 'NN02', NULL, NULL, 'Chester le Street Group', ' Please check our website walk programme for start times and venues.', 'https://www.ramblers.org.uk/chester-le-street', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/chester-le-street-group', '54.856440730000', '-1.591143602173', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(222, 'G', 'NN03', NULL, NULL, 'Sunderland Group', 'Secretary: Gillian Darbyshire, 14 Whittonstall, Fatfield, Washington, NE38 8PH  Telephone number 0191 417 2797.\r\n\r\nAll walks are circular and start at 10:30 am unless otherwise stated.  Length will be from 7 miles upwards.', 'https://www.ramblers.org.uk/northumbria', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/sunderland-group', '54.877534180000', '-1.444803921036', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(223, 'G', 'NN04', NULL, NULL, 'Gateshead Group', 'Our walks, of about 10 miles, are every Saturday starting at 10am. Please make your way to the start of the walk where the Walks Leader will greet you.', 'https://www.ramblers.org.uk/gateshead', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/gateshead-group', '54.944309270000', '-1.607027858123', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(224, 'G', 'NN05', NULL, NULL, 'Hexham Group', 'Secretary: Julia Forster; \r\n\r\nWalks co-ordinators: Nick Markson and Liz Alexander. \r\n\r\nWalks are held every Sunday, starting usually at 10.15am.', 'https://www.ramblers.org.uk/hexham', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/hexham-group', '55.059495660000', '-2.283161883791', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(225, 'G', 'NN06', NULL, NULL, 'Ponteland Group', 'We walk on alternate Sundays and two Wednesdays a month in Northumberland and North Durham. A variety of distances to suit all tastes.\r\n\r\n', 'https://www.ramblers.org.uk/ponteland', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/ponteland-group', '55.063423320000', '-1.859160575232', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(226, 'G', 'NN10', NULL, NULL, 'Berwick Group', 'For further information please contact Barbara-Jean Borthwick, Tel 01289 331176', 'https://www.ramblers.org.uk/berwick', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/berwick-group', '55.592634010000', '-1.993538170206', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(227, 'G', 'NN11', NULL, NULL, 'Alnwick Group', 'Walks Secretary : Heather Corby\r\nMeeting Place: Start of each walk\r\nAll Sunday walks start at 10am. If the weather is poor, check with the walk leader. Bring a packed lunch and something to drink.', 'https://www.ramblers.org.uk/alnwick', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/alnwick-group', '55.355074630000', '-1.919410876213', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(228, 'G', 'NN12', NULL, NULL, 'Derwentside Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.ramblers.org.uk/derwentside.aspx', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/derwentside-group', '54.829324990000', '-1.806829770351', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(229, 'G', 'NN13', NULL, NULL, 'Morpeth Group', 'Secretary: Tel 01670 511570\r\nMeeting Place: Unless stated otherwise, meet at Morpeth Leisure Centre car park at 9:30 a.m. ', 'https://www.ramblers.org.uk/northumbria', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/morpeth-group', '55.176438610000', '-1.688583420823', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(230, 'G', 'NN14', NULL, NULL, 'Durham City Group', 'The Durham City Group organises walks on Mondays in the summer and on Sunday, Wednesday and Friday throughout the year. If you are not a Ramblers member you are welcome to try up to three walks.', 'https://www.ramblers.org.uk/durham-city', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/durham-city-group', '54.766283960000', '-1.567061365457', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(231, 'S', 'NN30', NULL, NULL, 'Northumbria Short Circuits Group', 'Shorter walks of 4-6 miles at a leisurely pace in Northumberland and Durham.\r\nSorry dogs are not allowed on our walks. \r\nNew Members Welcome Please Contact Owen Oliver 01670 731340.\r\n\r\n', '', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/northumbria-short-circuits-group', '55.152016500000', '-1.998201220318', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(232, 'S', 'NN50', NULL, NULL, 'Northumbria Walking Group', 'Group aimed primarily at people in their 20s and 30s, but many members are in their 40\'s and early 50\'s.', 'https://www.northwalk.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/northumbria-walking-group', '55.199576340000', '-2.023008830860', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(233, 'S', 'NN70', NULL, NULL, 'Northumbria Family Walking Group', 'Simin Cooper \r\nCoordinator\r\n3 Roydon Avenue \r\nSunderland \r\nSR2 7TB \r\nTel : 0191 5108851 \r\nEmail : simincooper@talk21.', 'https://familywalking.org/about/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/northumbria-family-walking-group', '55.184576340000', '-1.963008830860', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(234, 'G', 'NP01', NULL, NULL, 'Northampton Group', 'We organise at least three walks per week led by local members, both short and long, and the occasional trip further afield. Get to know the area better, make new friends, and enjoy helping out. ', 'https://www.northamptonra.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/northampton-group', '52.136065660000', '-1.025014223312', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(235, 'G', 'NP02', NULL, NULL, 'Daventry Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.facebook.com/daventryramblers', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/daventry-group', '52.316050990000', '-1.048043822446', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(236, 'G', 'NP03', NULL, NULL, 'Wellingborough Group', 'We are a sociable group who provide a varied weekly schedule of interesting walks, led by local experts. Great for experiencing the outdoors, making new friends & increasing fitness.', 'https://ramblers.org.uk/wellingborough', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/wellingborough-group', '52.303458830000', '-0.653010959994', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(237, 'G', 'NP05', NULL, NULL, 'Kettering Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.northantsramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/kettering-group', '52.470978530000', '-0.615839230081', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(238, 'S', 'NP50', NULL, NULL, 'Northants 20s - 40s Ramblers Group', 'We are a group of people in their 20s, 30s and into their 40s from in and around Northamptonshire who enjoy walking, scrambling, climbing and generally having a bit of fun.\r\nOur walks are on most weekends and range from short local walks to longer ...', 'https://www.letsgetreadytoramble.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/northants-20s-40s-ramblers-group', '52.307632280000', '-0.834770494547', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(239, 'G', 'NR01', NULL, NULL, 'Kings Lynn Group', 'King\'s Lynn Ramblers are the largest walking group in West Norfolk offering over 200 walks a year. We offer a mix of Brisk, Short and Leisurely, Easy walking, Long and Evening walks.', 'https://www.kingslynnramblers.org', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/kings-lynn-group', '52.727130950000', '0.471033259556', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(240, 'G', 'NR02', NULL, NULL, 'Norwich Group', 'We offer walks off varying lengths on Sundays Wednesdays shorter walks on Saturdays and some evening walks in the summer and a variety of social events ', 'https://www.norwichra.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/norwich-group', '52.631833180000', '1.282784504420', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(241, 'G', 'NR03', NULL, NULL, 'Sheringham & District Group', 'Sheringham and District Ramblers is a friendly group . Our Wednesday walks are around 4 to 6 miles with a short stop and our Sunday walks are normally 6 to 10 miles again with a refreshment stop ', 'https://www.norfolkra.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/sheringham-district-group', '52.838831980000', '1.291027372113', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(242, 'G', 'NR04', NULL, NULL, 'Southern Norfolk', 'Our group runs walks on some Wednesdays, Thursday mornings (dogs welcome) and Sundays. We are a friendly group and welcome walkers of all abilities. Come and try us.', '', 'https://www.ramblers.org.uk/go-walking/group-finder/areas/norfolk/groups/southern-norfolk.aspx', '0.000000000000', '0.000000000000', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(243, 'G', 'NR06', NULL, NULL, 'Great Yarmouth Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.norfolkra.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/great-yarmouth-group', '52.640751680000', '1.661321034672', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(244, 'G', 'NR07', NULL, NULL, 'Wensum Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.norfolkra.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/wensum-group', '52.701193580000', '1.310201042431', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(245, 'G', 'NR08', NULL, NULL, 'Mid Norfolk Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.norfolkra.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/mid-norfolk-group', '52.588132520000', '0.837283013568', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(246, 'G', 'NR09', NULL, NULL, 'Fakenham Group', 'Fakenham Ramblers is a friendly group of walkers founded in 1990 and currently has 90 members. Due to Covid 19 our Walks Programme is restricted but we will offer at least 2 walks per month - Sat/Wed.', 'https://www.norfolkra.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/fakenham-group', '52.879334580000', '0.863454200058', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(247, 'S', 'NR30', NULL, NULL, 'Breckland Brisk Walkers Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness. You’re very welcome to try walking with us, or to get involved in looking after paths and green spaces and opening up new places to explore.', 'https://www.ramblers.org.uk/breckland-brisk-walker', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/breckland-brisk-walkers-group', '52.556584000000', '0.812511000000', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(248, 'S', 'NR50', NULL, NULL, 'Hike Norfolk Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://hikenorfolk.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/hike-norfolk-group', '52.675396660000', '0.975648813450', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(264, 'G', 'NY01', NULL, NULL, 'Barnard Castle Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.barnardcastleramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/barnard-castle-group', '54.595133740000', '-2.001148428857', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(265, 'G', 'NY02', NULL, NULL, 'Cleveland Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.ramblers.org.uk/cleveland', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/cleveland-group', '54.492028580000', '-1.034892991332', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(266, 'G', 'NY03', NULL, NULL, 'Crook & Weardale Group', 'We help people enjoy walking and protect the places we all love to walk. We organise weekly walks led by experienced leaders – a great way to get outside, make new friends and discover new places.', 'https://crookramblers.org/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/crook-weardale-group', '54.741341460000', '-1.990321254470', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(267, 'G', 'NY04', NULL, NULL, 'Darlington Group', 'Darlington Ramblers helps local people enjoy walking and protects the places we all love to walk. On our website you can find our walks programme, photographs from some of our walks and much more. ', 'https://sites.google.com/site/darlingtonramblers/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/darlington-group', '54.605799700000', '-1.532339976408', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(268, 'G', 'NY06', NULL, NULL, 'Northallerton Group', 'The numbers on all Northallerton Ramblers walks are limited. Booking is compulsory and starts 3 days before the walk date. Please email nrbookings@northallertonramblers.org.uk for booking instructions', 'https://www.northallertonramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/northallerton-group', '54.334972720000', '-1.382088303800', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(269, 'G', 'NY07', NULL, NULL, 'Richmondshire Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.richmondshireramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/richmondshire-group', '54.361515240000', '-1.934051614054', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(270, 'S', 'NY50', NULL, NULL, 'Darlington Dales and Hills Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.darlingtonhiking.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/darlington-dales-and-hills-group', '54.477243230000', '-1.529079287101', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(271, 'G', 'OX01', NULL, NULL, 'Banbury and North Oxfordshire Ramblers', 'Banbury and North Oxfordshire group is centred on the picturesque market town of Banbury, complete with its statue of the fine lady on a white horse!  Set amid gentle hills and rolling farmland ...', 'https://www.ramblers-oxon.org.uk/bno', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/banbury-and-north-oxfordshire-ramblers', '52.048512490000', '-1.386698448108', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(272, 'G', 'OX02', NULL, NULL, 'Oxford Group', 'One of the biggest Groups in the Oxfordshire Area, city based membership, but walks all over.  Unless stated otherwise, dogs are allowed, but preferably on leads.', 'https://www.ramblers-oxon.org.uk/Oxford.html', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/oxford-group', '51.754591750000', '-1.240976012145', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(273, 'G', 'OX04', NULL, NULL, 'Vale of White Horse Group', 'Our usual walking area includes the White Horse at Uffington, the river Thames and the Ridgeway National Trail. Abingdon, Wantage and Faringdon are all local market towns.', 'https://www.ramblers-oxon.org.uk/vwh.html', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/vale-white-horse-group', '51.634234400000', '-1.441605653626', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(274, 'G', 'OX05', NULL, NULL, 'West Oxfordshire Group', 'Walkers from West Oxfordshire out and about.  For more information contact Alan Cobb.\r\nUnless stated otherwise, dogs are allowed, but preferably on their leads.', 'https://www.ramblers-oxon.org.uk/west-oxfordshire.', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/west-oxfordshire-group', '51.837661560000', '-1.506862617005', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(275, 'G', 'OX06', NULL, NULL, 'Bicester & Kidlington Group', 'The area has as its main features and special attractions, the Oxford canal\r\nwith its quaint canal side hostelries and tow path walking.  Houses built of\r\nCotswold stone, and of course, Blenheim Palace.  Unless stated otherwise, dogs are allowed ...', 'https://www.ramblers-oxon.org.uk/bicester-kidlingt', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/bicester-kidlington-group', '51.897296140000', '-1.199656981703', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(276, 'G', 'OX07', NULL, NULL, 'Didcot & Wallingford Group', 'The Didcot & Wallingford group contributes over 50 walks a year to the area programme, as well as arranging an annual weekend away in various locations in England and Wales. New walkers and potential members are always welcome. The group has strong ...', 'https://www.ramblers-oxon.org.uk/didcot-wallingfor', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/didcot-wallingford-group', '51.610244470000', '-1.154903074542', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(277, 'G', 'OX08', NULL, NULL, 'Henley & Goring Group', 'Combine healthy exercise with meeting a friendly and sociable group of people! Join Henley & Goring Ramblers for walks in an area of outstanding natural beauty. Enjoy a walk along the Thames, in the hills and beech woods of the Chilterns, through ...', 'https://www.ramblers-oxon.org.uk/henley-goring.htm', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/henley-goring-group', '51.563442440000', '-1.024704976376', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(278, 'G', 'OX09', NULL, NULL, 'Thame & Wheatley Group', 'We enjoy walks of varying levels and distances every week, as well as arranging holidays and social events.  Our active path maintenance team helps to keep the footpaths clear.', 'https://www.ramblers-oxon.org.uk/thame-wheatley.ht', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/thame-wheatley-group', '51.705462430000', '-1.050801283166', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(279, 'S', 'OX40', NULL, NULL, 'Oxon Weekend Walkers Group', 'A walking group for people in the midst of their working lives, keen to get out and walk at the weekend, enjoy walking weekends away and social events too, plus a great way to make new friends.  Unless stated otherwise, dogs are allowed, but ...', 'https://oxonww.org/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/oxon-weekend-walkers-group', '51.765621990000', '-1.352534610879', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(280, 'S', 'OX50', NULL, NULL, 'Hike Oxfordshire', 'For people in and around Oxfordshire in their 20s & 30s interested in walking, social events and weekends away.', 'https://hikeoxfordshire.org/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/hike-oxfordshire', '51.765621990000', '-1.292534610879', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(281, 'S', 'OX70', NULL, NULL, 'Blitz and Klean  Group', 'Bicester & Kidlington Group’s working party operates in the same territory as the main walking group and meets at least once a month on various days of the week to accommodate all interested parties.', 'https://www.ramblers-oxon.org.uk/blitz-clean.html', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/blitz-and-klean-group', '51.896478740000', '-1.208492741445', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(282, 'G', 'SD01', NULL, NULL, 'Chesterfield & North East Derbyshire Group', 'A Group that organises in excess of 350 walks per annum that are accessible to people in the Chesterfield and North East Derbyshire area.\r\n\r\nFrom short to long, car to bus, easy to strenuous.', 'https://chesterfieldramblers.com/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/chesterfield-north-east-derbyshire-group', '53.226640510000', '-1.387483632830', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(283, 'G', 'SD02', NULL, NULL, 'Doncaster Group', 'The Doncaster Group walks on Tuesdays, Thursdays and Saturdays throughout the year,  The Thursday walks are shorter walks of 5-6 miles suitable for active people who wish to improve their walking.', 'https://doncasterramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/doncaster-group', '53.544344530000', '-1.095689671080', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(284, 'G', 'SD03', NULL, NULL, 'Sheffield Group', 'Meet at the bus or train station unless a different meeting point is given in the desciption.\r\n\r\nPlease check our web site, http://www.sheffieldramblers.org, for up to date walk information.', 'https://www.sheffieldramblers.org', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/sheffield-group', '53.404425450000', '-1.550502990945', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(285, 'G', 'SD04', NULL, NULL, 'Rotherham Metro District Group', 'A friendly,welcoming group that walks every Saturday and  Wednesday. Walks to suit everyone take place in the local Rotherham area or in areas of South and West Yorkshire, the White and Dark Peak', 'https://www.ramblers.org.uk/rotherham-metro', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/rotherham-metro-district-group', '53.460719080000', '-1.352654374300', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(286, 'G', 'SD05', NULL, NULL, 'Barnsley & Penistone Group', 'The Barnsley & Penistone group aims to help local people, regardless of age, ability, sex or race to enjoy walking. You are warmly invited to join us.', 'https://www.ramblers.org.uk/barnsley-penistone', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/barnsley-penistone-group', '53.535827480000', '-1.532519214386', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(287, 'G', 'SD07', NULL, NULL, 'Dearne Valley Group', 'The Dearne Valley covers the area between Rotherham, Barnsley and Doncaster, and includes Swinton, Wath-upon-Dearne and Mexborough.  Several of our walks are within this area, often taking advantage of the Trans-Pennine Trail and other regenerated ...', 'https://www.dearnevalleyramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/dearne-valley-group', '53.374874000000', '-1.243174139991', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(288, 'S', 'SD50', NULL, NULL, 'Sheffield 20s & 30s Group', 'Sheffield 20s and 30s walking group put on walks in the Sheffield area most Saturdays and Sundays, ranging from leisurely to strenuous. Our walks are mostly in the Peak area, but we also arrange booked weekends away to more distant countryside.\r\nThe ...', 'https://www.sheffieldwalkinggroup.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/sheffield-20s-30s-group', '53.404301220000', '-1.520617791118', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(289, 'S', 'SD52', NULL, NULL, 'Sheffield 40s Group', 'The Sheffield 40s has over 200 members who love walking in the Peak District and farther afield, meeting socially for a drink or two (walks end in pubs) and going away for the occasional weekend.', 'https://www.s40wg.org/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/sheffield-40s-group', '53.404301220000', '-1.550617791118', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(290, 'G', 'SK01', NULL, NULL, 'Bury St Edmunds Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.burystedmundsramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/bury-st-edmunds-group', '52.314168130000', '0.669268140667', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
