(299, 'G', 'SO01', NULL, NULL, 'Mendip Group', 'Mendip Group arranges shorter walks on a Thursday and longer walks on a Sunday. We have plenty of social events and pub walks and organise holidays and weekends away for our members. Our walks are usually in the Mendips - an Area of Outstanding ...', 'https://www.mendipramblers.co.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/mendip-group', '51.202890310000', '-2.544542945927', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
