(305, 'G', 'SR01', NULL, NULL, 'Croydon Group', 'We are a large group offering 10+ walks a week. Visit our website for more information. We also have group walking holidays in the UK and abroad.  Our working party does footpath work for Surrey CC.', 'https://www.croydonramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/croydon-group', '51.355334700000', '-0.087155662824', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(306, 'G', 'SR02', NULL, NULL, 'East Surrey Walkers Group', 'East Surrey Walkers was formed in 1983, originally as East Surrey Ramblers, & has around 500 members. We\'re a sociable group; our aim is to enjoy walking in the countryside of Surrey, Kent and Sussex.', 'https://www.eastsurreywalkers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/east-surrey-walkers-group', '51.224848620000', '-0.048369101862', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(307, 'G', 'SR03', NULL, NULL, 'Farnham & District Group', 'We are a sociable group whose primary aim is for our members to enjoy walking in the countryside with an interesting variety of scenery; we walk in SW Surrey, E Hampshire and W Sussex.  We organise regular weekly walks on several days of the week ...', 'https://www.farnhamramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/farnham-district-group', '51.188309980000', '-0.776507633150', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(308, 'G', 'SR04', NULL, NULL, 'Godalming & Haslemere Group', 'We organise weekly walks, walking weekends away in other parts of the country, longer walking holidays in Europe, and social events. Walks are arranged for every Wednesday, Thursday and Sunday.', 'https://www.gandhramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/godalming-haslemere-group', '51.137975630000', '-0.588566988040', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(309, 'G', 'SR05', NULL, NULL, 'Kingston Group', 'Kingston Ramblers lead walks every weekend and midweek in the countryside of Surrey, Hampshire, Sussex, etc.\r\n\r\nMost destinations are reached by public transport, although Sunday ramblers usually travel by car.\r\n\r\nThe meeting place to share cars is ...', 'https://www.kingston-ramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/kingston-group', '51.372428110000', '-0.343466366290', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(310, 'G', 'SR06', NULL, NULL, 'Mole Valley Group', 'If you are interested in walking in the beautiful Surrey countryside, then join us on a Mole Valley Ramble. Every week we have walks catering for a range of abilities - see our website for details.', 'https://www.molevalleyramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/mole-valley-group', '51.212316380000', '-0.325116875275', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(311, 'G', 'SR07', NULL, NULL, 'Richmond Group', 'The Richmond Group has a varied programme of walks at weekends and during mid-week. All walks are conveniently organised around public transport.\r\n\r\nHaving a very large proportion of open land in Richmond and Twickenham, as well as a long section of ...', 'https://www.richmondramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/richmond-group', '51.442748650000', '-0.312350812512', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(312, 'G', 'SR08', NULL, NULL, 'Woking Group', 'A friendly group whose prime purpose is to enjoy the beautiful local countryside. We have a good spread of short and long walks, ranging from 2 miles to 15 miles.', 'https://www.ramblers.org.uk/woking', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/woking-group', '51.313877670000', '-0.560759695727', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(313, 'G', 'SR10', NULL, NULL, 'Epsom & Ewell Group', 'The Epsom and Ewell Group walk three or four times a week usually in Surrey. \r\nSome members of the group enjoy a walking holiday most years, and occasional social events.', 'https://www.epsomandewellramblers.co.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/epsom-ewell-group', '51.339172820000', '-0.261446111858', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(314, 'G', 'SR11', NULL, NULL, 'Guildford Group', 'A sociable group whose primary purpose is to enjoy the beautiful local countryside. Walks span Dorking in the east to Alresford in the west and both the North and South downs. ', 'https://www.guildfordramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/guildford-group', '51.247782340000', '-0.561637243966', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(315, 'G', 'SR12', NULL, NULL, 'Reigate Group', 'A friendly and sociable group, we have walks in the week and at weekends, usually between 4 and 9 miles in length. Please visit our website to find out about our varied walking and social activities.', 'https://www.reigateramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/reigate-group', '51.257921800000', '-0.194937982427', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(316, 'G', 'SR13', NULL, NULL, 'Staines Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.stainesramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/staines-group', '51.406080350000', '-0.512282668051', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(317, 'G', 'SR14', NULL, NULL, 'Sutton/Wandle Valley Group', 'The Group provides a wide range of walks from 2 miles upwards and over half the walks can easily be reached by public transport.  For walks using cars, the usual meeting point for car sharing is Belmont Bus Terminal adjacent to Belmont Station.', 'https://suttonwandleramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/suttonwandle-valley-group', '51.370205260000', '-0.178863016046', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(318, 'G', 'SR15', NULL, NULL, 'Surrey Heath Group', 'We are a vibrant and friendly group who welcome new, old and visiting walkers alike. Our led walks vary from 90 minutes to 4 hours in duration and are all within 40 minutes drive of our home area.In addition to our walks we organise several holidays each year. Come and join is and find out more.', 'https://www.surreyheathramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/surrey-heath-group', '51.342927970000', '-0.670523239746', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(319, 'S', 'SR50', NULL, NULL, 'Surrey Young Walkers Group', 'Surrey Young Walkers (SYW) hold walks every weekend, in and around Surrey, as well as social events, weekends away and walking holidays. For the current programme and to find out more...', 'https://surreyyoungwalkers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/surrey-young-walkers-group', '51.282257480000', '-0.419925696770', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(320, 'S', 'SR51', NULL, NULL, 'Surrey and Beyond Ramblers (SABRE) Group', 'Surrey and Beyond Ramblers (SABRE) is one of a new generation of Ramblers groups that is internet based. Our mission is to encourage everybody to get out there and walk over Surrey and beyond.', 'https://www.sabre-walkers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/surrey-and-beyond-ramblers-sabre-group', '51.267257480000', '-0.359925696770', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(321, 'G', 'SS02', NULL, NULL, 'Telford & East Shropshire Group', 'Telford and East Shropshire Ramblers helps local people enjoy walking, leads Group walks and maintains and protects footpaths. Car share to walk starts meet Telford Forge Retail Park (FRP) ', 'https://tesramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/telford-east-shropshire-group', '52.608691250000', '-2.439145412688', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(322, 'G', 'SS03', NULL, NULL, 'Market Drayton Group', 'Days Sundays and Tuesdays\r\nLength and difficulty: Sundays 11km/7 miles to 22km/14 miles, graded leisurely  to strenuous. Tuesdays 8km/5 miles to 10km /6miles, graded leisurely to strenuous.', 'https://www.ramblers.org.uk/market-drayton', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/market-drayton-group', '52.889703770000', '-2.587151785291', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(323, 'G', 'SS04', NULL, NULL, 'Oswestry Group', 'Oswestry Group walk on Thursdays & Sundays. Near Oswestry and elsewhere in Shropshire, Cheshire, mid & north Wales.  Also, social events, away days, holidays and path maintenance team. Join us!', 'https://www.ramblers.org.uk/oswestry', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/oswestry-group', '52.858370220000', '-2.985906031171', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(324, 'G', 'SS05', NULL, NULL, 'South Shropshire Group', 'South Shropshire is hill country, interlaced with beautiful streams, rivers and valleys.  Walking here can be demanding, but the rewards are fantastic.   Please book your place on a walk.', 'https://www.ramblers.org.uk/south-shropshire', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/south-shropshire-group', '52.463389340000', '-2.856440040921', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(325, 'G', 'SS06', NULL, NULL, 'Shrewsbury Group', 'The group walks of various lengths on Tuesdays, Thursdays and Sundays with Wednesday evening walks in the Summer. The programme offers coach trips , holidays ,and footpath maintenance. Join Us!', 'https://www.ramblers.org.uk/shrewsbury', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/shrewsbury-group', '52.699350840000', '-2.787157657817', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(326, 'S', 'SS50', NULL, NULL, 'Shropshire Young Ramblers Group', 'SYR is a group of like minded younger people who love being outdoors. We have a walk on most weekends, as well as social events and weekends away. Join us on a walk to find out more!', 'https://www.syr.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/shropshire-young-ramblers-group', '52.643424970000', '-2.683658006502', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
