(328, 'G', 'SX02', NULL, NULL, 'Brighton & Hove Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.bahr.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/brighton-hove-group', '50.864639800000', '-0.057444191496', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
