(330, 'G', 'SX04', NULL, NULL, 'Mid Sussex Group', 'We offer a variety of walks from 3 to 12 miles, Saturdays, Sundays, Tuesdays and Thursdays from around the Haywards Heath area, including Ashdown Forest and the South Downs.', 'https://www.midsussexramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/mid-sussex-group', '51.008396910000', '-0.117212884556', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(331, 'G', 'SX05', NULL, NULL, 'Crawley & North Sussex Group', 'Our group comprises of about 250 members and we offer a variety of walks from 5-13 miles within Sussex, Surrey and Kent, mainly on a Saturday or Sunday, with additional evening walks held during the Summer months.  Our group shares a love of walking ...', 'https://www.crawleyramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/crawley-north-sussex-group', '51.044437400000', '-0.355131064668', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(332, 'G', 'SX06', NULL, NULL, 'South West Sussex Group', 'With the city of Chichester at its heart, South West Sussex Group, offers a range of Group Walks, with up to three per week, all led by members with a wealth of knowledge  in this part of the County.', 'https://www.ramblers.org.uk/south-west-sussex', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/south-west-sussex-group', '50.926055210000', '-0.691301025171', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(333, 'G', 'SX07', NULL, NULL, 'Beachy Head Group', 'We are The Beachy Head Ramblers. We organise walks all over East Sussex.', 'https://www.beachyheadramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/beachy-head-group', '50.854809010000', '0.201544101320', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(334, 'G', 'SX08', NULL, NULL, 'Rother Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.rotherramblers.org.uk/about.htm', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/rother-group', '50.930368090000', '0.568968048916', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
