(336, 'S', 'SX50', NULL, NULL, 'Sussex Young Walkers Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.sussex-young-walkers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/sussex-young-walkers-group', '50.946833870000', '-0.109896651621', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(337, 'G', 'WE01', NULL, NULL, 'North West Wiltshire Group', 'Where the Cotswolds Area of Outstanding Natural Beauty (AONB) meets the Wiltshire Downs can best describe the charming area in which the North West Wiltshire group regularly walk. ', 'https://nw.wiltsswindonramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/north-west-wiltshire-group', '51.509456180000', '-2.095459291818', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(338, 'G', 'WE02', NULL, NULL, 'Mid Wiltshire Group', 'Our group covers the area in central Wiltshire bounded by the Marlborough Downs in the north and Salisbury Plain to the south. It includes the historic town of Devizes and several attractive villages.', 'https://mid.wiltsswindonramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/mid-wiltshire-group', '51.318621640000', '-1.885510327814', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(339, 'G', 'WE03', NULL, NULL, 'South Wiltshire Group', 'Based on the Cathedral City of Salisbury the South Wiltshire group meets mainly on a Tuesday and Thursday for shorter walks and on Sundays for all day walks. We have a varied programme of walks ...', 'https://south.wiltsswindonramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/south-wiltshire-group', '51.090885050000', '-1.920238712352', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL);
