(340, 'G', 'WE04', NULL, NULL, 'Swindon & North East Wilts Group', 'The Swindon and North East Wiltshire group covers the towns of Swindon and Marlborough and a large area of beautiful and varied countryside surrounding them.', 'https://ne.wiltsswindonramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/swindon-north-east-wilts-group', '51.473758150000', '-1.732182674379', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(341, 'G', 'WE05', NULL, NULL, 'West Wiltshire Group', 'The West Wiltshire area comprises five main towns i.e. Bradford-on-Avon, Melksham, Trowbridge, Warminster, Westbury, and many villages. The open spaces of the Westbury hills - chalk downlands to the south and east of Warminster - offer walking ...', 'https://west.wiltsswindonramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/west-wiltshire-group', '51.254707490000', '-2.153056196115', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(342, 'G', 'WK01', NULL, NULL, 'City of Birmingham Group', 'Our programme includes easy short walks on Thursdays and Saturdays by public transport, plus three levels of walk via our Sunday coach rambles and Wednesday walks with a pub lunch.', 'https://www.ramblers.org.uk/city-of-birmingham', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/city-birmingham-group', '52.472757770000', '-1.877146798780', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(343, 'G', 'WK02', NULL, NULL, 'Coventry Group', 'Coventry Ramblers organise regular walks in and around Coventry – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.ramblers.org.uk/coventry', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/coventry-group', '52.500657450000', '-1.575692879147', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(344, 'G', 'WK03', NULL, NULL, 'Mid Warwickshire Group', 'The Group has summer and winter walks programmes, based on weekly Sunday walks, with evening midweek walks in summer. Warwickshire is a county of rich farmland and pleasant towns and villages. In addition, The Cotswolds, The Malverns, the Chilterns ...', 'https://www.midwarksramblers.org', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/mid-warwickshire-group', '52.310004230000', '-1.584683436921', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(345, 'G', 'WK04', NULL, NULL, 'Rugby Group', 'The group has a full programme of walks, midweek and weekends throughout the year.  The length of walks varies from short local walks of 3 to 5 miles to longer walks of up to 16 miles.  For short local walks we meet at the start of the walk but ...', 'https://www.rugbyramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/rugby-group', '52.384436580000', '-1.328344661367', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(346, 'G', 'WK05', NULL, NULL, 'Stratford upon Avon Group', '', 'https://www.stratfordramblers.com', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/stratford-upon-avon-group', '52.171688020000', '-1.732787992510', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(347, 'G', 'WK06', NULL, NULL, 'Southam Group', 'W​alks are held on alternate Wednesday mornings throughout the year with Summer Strolls on alternate Thursday evenings from May to mid-August. For all walks meet in the Wood Street car park in Southam', 'https://www.southamramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/southam-group', '52.191147300000', '-1.455148326549', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(348, 'G', 'WK07', NULL, NULL, 'Solihull Group', 'The Group was formed in 1987 and our members are from in and around the Solihull postcode areas. We have a varied programme of walks and events throughout the year, and new members are always welcome.', 'https://www.solihullramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/solihull-group', '52.409668630000', '-1.761178349687', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(349, 'G', 'WK08', NULL, NULL, 'Sutton Coldfield Group', 'Founded in 1991, we are a thriving Group based in Sutton Coldfield.  We have approximately 300 members and offer a wide variety of events to suit most age groups and abilities.', 'https://suttoncoldfieldramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/sutton-coldfield-group', '52.551157600000', '-1.824870649110', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(350, 'G', 'WK09', NULL, NULL, 'Castle Bromwich Group', '\"Your Local Friendly Walking Group\" .... That\'s what people call us. We\'re a happy bunch, always welcoming, and on the look out for new recruits! All abilities very welcome. Come and see for yourself.', 'https://www.castlebromwichramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/castle-bromwich-group', '52.503356570000', '-1.695225588402', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(351, 'G', 'WK10', NULL, NULL, 'South Birmingham Group', 'Our walks take us to many of the counties in the Midlands, and beyond on our weekends away. We offer at least 3 walk every week one of which is 5 miles or less.', 'https://www.sbramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/south-birmingham-group', '52.416655770000', '-1.964417052337', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(352, 'S', 'WK51', NULL, NULL, 'West Midlands Walking Group', 'West Midlands Walking has more than 200 members and is for walkers in their 20s to 40s based covering an area including the West Midlands, Warwickshire and Worcestershire.', 'https://www.wmwg.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/west-midlands-walking-group', '52.317968730000', '-1.603230807599', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(353, 'S', 'WK52', NULL, NULL, 'The Bears Group', 'A walking group for people living in and around Warwickshire in their 20s, 30s and 40s.  Walks predominantly in Warwickshire and the Cotswolds though sometimes venturing out to Worcestershire, Shropshire, Staffordshire and Leicestershire.  We also ...', 'https://www.bearwalkinggroup.co.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/bears-group', '52.347968730000', '-1.633230807599', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(354, 'S', 'WK53', NULL, NULL, 'West Midlands 40+  Group', 'A friendly group of over 40’s enjoying walking throughout the West Midlands including Staffordshire, Warwickshire and Shropshire. We also arrange walking weekends and holidays and social events.', 'https://www.meetup.com/West-Midlands-40-Walking-Gr', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/west-midlands-40-group', '52.332968730000', '-1.573230807599', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(355, 'G', 'WO01', NULL, NULL, 'Bromsgrove Group', 'Bromsgrove group walk in the local area at least three times a month plus social events throughout the year.', 'https://bromsgroveramblers.webs.com', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/bromsgrove-group', '52.361760700000', '-2.016036788493', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(356, 'G', 'WO02', NULL, NULL, 'Wyre Forest Group', 'Wyre Forest is a friendly mixed age group which organises varied weekly walks ,both locally and further afield, of approximately 5 -14 miles.  We also organise occasional weekend walking breaks in the', 'https://www.ramblers.org.uk/wyre-forest', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/wyre-forest-group', '52.379574040000', '-2.274647266260', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(357, 'G', 'WO03', NULL, NULL, 'Redditch Group', 'The Redditch website is at http://www.redditchramblers.org.uk.  We are a friendly and socialable group. We normally have a stop for coffee and lunch - bring your own fo', 'https://www.redditchramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/redditch-group', '52.282291560000', '-1.951838228408', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(358, 'G', 'WO05', NULL, NULL, 'Evesham Group', 'Our friendly group of walkers offer a four monthly programme of walks on Sundays and lots of Tuesdays, some evening walks and regular social events. Come along and join in. Dogs welcome on most walks.', 'https://eveshamramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/evesham-group', '52.096160000000', '-1.975645185819', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(359, 'G', 'WO06', NULL, NULL, 'Worcester Group', 'Worcester Ramblers is a friendly and sociable group of walkers who like to share the enjoyment of walking in the countryside, participating in working parties and social events.', 'https://www.worcesterramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/worcester-group', '52.200469130000', '-2.262258398205', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(360, 'G', 'WR01', NULL, NULL, 'Bradford Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.ramblers.org.uk/bradford', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/bradford-group', '53.808889530000', '-1.791077515275', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
