(365, 'G', 'WR07', NULL, NULL, 'Huddersfield Group', 'Welcome to walking with Huddersfield Group! We have at least one walk every Sunday, sometimes local to Huddersfield, sometimes further afield. Also, monthly \"A+\" grade walks on Saturdays for those who enjoy something more energetic! Walks of up to 5 ...', 'https://www.ramblers.org.uk/huddersfield', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/huddersfield-group', '53.600561560000', '-1.810322841527', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(366, 'G', 'WR08', NULL, NULL, 'Keighley Group', 'We are a friendly group of like-minded people who enjoy nothing better than to explore the lovely and varied countryside of West Yorkshire and neighbouring counties in sociable company.  ', 'https://www.ramblers.org.uk/keighley', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/keighley-group', '53.862088830000', '-1.939355238714', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
