(368, 'G', 'WR10', NULL, NULL, 'Lower Wharfedale Group', 'Lower Wharfedale Ramblers put on 5 walks a week on Tuesdays and Thursdays. You may need to book via so please visit our website https://lowerwharfedaleramblers.co.uk', 'https://www.lowerwharfedaleramblers.co.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/lower-wharfedale-group', '53.906501340000', '-1.795120614509', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
