(370, 'G', 'WR15', NULL, NULL, 'Wakefield and District Ramblers Group', 'Wakefield and District Ramblers aim to offer at least one walk per week throughout the year, ranging from 4 to 10 miles, everyone is welcome so please feel free to join us on any of our walks.', 'https://www.ramblers.org.uk/wakefield-district', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/wakefield-and-district-ramblers-group', '53.660662720000', '-1.411802558205', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(371, 'G', 'WR60', NULL, NULL, 'Wetherby Walking  Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness. You’re very welcome to try walking with us, or to get involved in looking after paths and green spaces and opening up new places to explore. ', 'https://www.ramblers.org.uk/wetherby-district', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/wetherby-walking-group', '53.801150930000', '-1.227338476242', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(372, 'S', 'WR50', NULL, NULL, 'Take a Hike Group', 'A Group aimed primarily at walkers in their 20s, 30s and 40s.', 'https://www.takeahike.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/take-hike-group', '53.911709580000', '-1.701159075047', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(373, 'G', 'WX01', NULL, NULL, 'Alton Group', 'We cover a large area of East Hampshire and the South Downs, with an interesting variety of scenery.  There is always a mid-week walk of approximately 5 miles, and frequently longer ones on the same day, a Sunday walk, normally of about 10 miles ...', 'https://www.altonramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/alton-group', '51.135725660000', '-0.976700922000', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(374, 'G', 'WX02', NULL, NULL, 'Andover Group', 'We would like to invite you to walk regularly with us in a beautiful part of Hampshire characterized by chalk downland, sparkling rivers and idyllic villages. We offer a wide variety of walks, in terms of location, distance, grade and type, and with ...', 'https://andoverramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/andover-group', '51.216042820000', '-1.496160113613', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(375, 'G', 'WX03', NULL, NULL, 'Meon Group', 'The Meon Group offers 3 walks of varying lengths every Sunday throughout the year with some mid-week walks.  Our walks are mainly in Hampshire and West Sussex with occasional trips across to the Isle of Wight.  Extras include coach based walks  and ...', 'https://www.ramblers.org.uk/meon', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/meon-group', '50.864150330000', '-1.180165373933', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(376, 'G', 'WX04', NULL, NULL, 'New Forest Group', 'The New Forest Group walkers enjoy exploring the New Forest and also the area from West Dorset to East Hampshire to South Wiltshire.  Come and try a walk with our very friendly group.   ', 'https://www.newforestramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/new-forest-group', '50.856863050000', '-1.650611471119', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(377, 'G', 'WX05', NULL, NULL, 'North East Hants Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.ramblers.org.uk/north-east-hants', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/north-east-hants-group', '51.283091860000', '-0.877509962502', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(378, 'G', 'WX06', NULL, NULL, 'Portsmouth Group', 'We walk predominately in South East Hampshire and West Sussex. Saturday walks are usually 7 miles. Sunday walks are around 12 miles and normally have a lunch time pub stop. ', 'https://www.portsmouthramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/portsmouth-group', '50.820488350000', '-1.078444430898', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(379, 'G', 'WX07', NULL, NULL, 'Romsey Group', 'We walk around Romsey, in the New Forest, Hampshire and neighbouring counties.  Short Saturday walks are intended for the new walker and are of 4 or 5 miles.  Midweek walks may be 6-12 miles and are often at a moderate pace. Sunday walks are usually ...', 'https://www.ramblers.org.uk/romsey', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/romsey-group', '51.064327970000', '-1.536003768970', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(380, 'G', 'WX08', NULL, NULL, 'Southampton Group', 'Welcome to Southampton Ramblers. We offer friendly welcoming company and cater for all abilities. Walks take place Thursday - Sunday with different distances and pace. ', 'https://www.ramblers.org.uk/southampton', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/southampton-group', '50.908064010000', '-1.420219476150', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(381, 'G', 'WX09', NULL, NULL, 'South East Hants Group', 'We are friendly group that walks in the SE Hants/W Sussex area (Rowlands Castle, Petersfield, Selborne, Meon Valley, Chichester, Midhurst etc...), with a number of walks on the South Downs.', 'https://www.sehampshireramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/south-east-hants-group', '50.976317490000', '-0.960292378708', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(382, 'G', 'WX10', NULL, NULL, 'Winchester Group', 'We have a comprehensive programme of walks and work to protect paths and the local countryside. We also carry out practical tasks such as clearing overgrown paths and replacing stiles with gates.', 'https://www.ramblers.org.uk/winchester', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/winchester-group', '51.081994710000', '-1.265679916120', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(383, 'G', 'WX11', NULL, NULL, 'Waltham Group', 'We are a small friendly group who regularly walk on Wednesday mornings. The walks usually being about 5 miles long.  Most Sundays we have a longer walk of 8 -10 miles, with a picnic lunch. In summer we also have walks of 4-5 miles on Friday evenings.', 'https://www.harrogateramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/waltham-group', '50.969746070000', '-1.175746156316', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(384, 'G', 'WX12', NULL, NULL, 'Eastleigh Group', 'Our Eastleigh Ramblers group offers walks on most Saturdays and Sundays and a mid-week morning walk on a Thursday. We also have group walks following National Trails on other days.', 'https://eastleighramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/eastleigh-group', '50.933054420000', '-1.327222648016', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(385, 'G', 'WX13', NULL, NULL, 'North Hampshire Downs Group', 'The North Hampshire Downs Ramblers Group represents the local group of the Ramblers covering Basingstoke and the surrounding area. The group walks primarily on Tuesday and Saturdays.', 'https://www.northhampshiredownsramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/north-hampshire-downs-group', '51.273459930000', '-1.200986590208', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
