(433, 'S', 'SL50', NULL, NULL, 'Glasgow Young Walkers Group', 'For more pictures and chit chat you can also find us on Facebook- https://www.facebook.com/groups/1723794561209293/', 'https://glasgowyoungwalkers.ning.com/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/glasgow-young-walkers-group', '55.890436400000', '-5.226738992215', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(434, 'G', 'SC01', NULL, NULL, 'Badenoch & Strathspey Group', 'Our area includes the Monadh Liath and the high tops of the Cairngorms, the birch and pine woodlands of the Spey Valley, beautiful Glen Feshie, and much more besides', 'https://www.badenochandstrathspeyramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/badenoch-strathspey-group', '57.109701020000', '-3.977097570707', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(435, 'G', 'SC02', NULL, NULL, 'Lochaber & Lorn Group', 'Our area has the best walking in the UK. It includes Ben Nevis, spectacular Glen Coe and the islands of Skye, Mull, Rum and Eigg. We walk two days every week.Thursdays and alternate Sat/Sun.', 'https://www.lochaberandlorn-ramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/lochaber-lorn-group', '56.686067620000', '-5.396210554267', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(436, 'G', 'SC06', NULL, NULL, 'Inverness Group', 'Walks every week, alternating Saturday/Sunday. Mountain, forest, lochside and coastal walks of varying grade. You\'ll find a warm welcome awaits you!', 'https://www.ramblers.org.uk/inverness', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/inverness-group', '58.055114860000', '-4.684977925042', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(437, 'G', 'WS01', NULL, NULL, 'Cunninghame Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://mikemcguire1.wix.com/cunninghame-ramblers', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/cunninghame-group', '55.625660080000', '-5.002201071697', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(438, 'G', 'WS02', NULL, NULL, 'Kilmarnock & Loudoun Group', 'Our group helps local people enjoy walking and protect the places we all love to walk. \r\nAll our walks are led by willing volunteers to enable our members to enjoy walks all around Southwest Scotland', 'https://kilmarnockramblers.jimdofree.com', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/kilmarnock-loudoun-group', '55.485361140000', '-4.314340706546', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(439, 'G', 'WS03', NULL, NULL, 'South Ayrshire', '', '', '', '55.268756900000', '-4.688584000000', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(440, 'G', 'WS04', NULL, NULL, 'Wigtownshire Group', 'We currently walk on Saturdays and occasional Sundays, year round, with a varied programme to meet members requirements. Our area ranges from the Rhins of Galloway in the west through the Machars to the Gatehouse of Fleet area in the east, taking in ...', 'https://www.ramblers.org.uk/wigtownshire', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/wigtownshire-group', '54.921243500000', '-4.665610716771', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(441, 'G', 'CA01', NULL, NULL, 'Carmarthen & District Group', 'Based in Carmarthen in West Wales we consider ourselves to be a friendly group always open to visitors and new members. Full details are available on our website. \r\nOur programme comprises mainly Sunday walks with a shorter walk (say 4-5 miles ) on ...', 'https://www.carmarthenramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/carmarthen-district-group', '51.893959630000', '-4.370417415872', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(442, 'G', 'CA02', NULL, NULL, 'Dinefwr Group', 'We are a friendly group based in south west Wales, walking in the beautiful Carmarthenshire countryside, the Brecon Beacons and on the coast. We offer 2 led walks each week...', 'https://www.dinefwrramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/dinefwr-group', '51.955427030000', '-3.915431431514', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(443, 'G', 'CA03', NULL, NULL, 'Llanelli Group', 'A friendly and active Group, with walks on Mondays (easy walks for over-60s), Wednesdays, Saturdays/Sundays, and - during summer months - Thursday evening family walks. In addition, monthly Tuesday walks (2nd Tuesday of each month), May to September ...', 'https://www.llanelliramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/llanelli-group', '51.720890900000', '-4.190722976622', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(444, 'G', 'SW01', NULL, NULL, 'Cardiff Group', 'Cardiff group organises walks in the south Wales area and beyond, including the Brecon Beacons, Black Mountains, Gower, Wye Valley and many other locations. Walks vary from 2 to 20 miles, and happen on Wednesdays (3 different distances), weekends ...', 'https://www.cardifframblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/cardiff-group', '51.508428170000', '-3.199544540180', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(445, 'G', 'SW02', NULL, NULL, 'Neath Port Talbot Group', '', 'https://www.neathporttalbotramblers.co.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/neath-port-talbot-group', '51.679766450000', '-3.743403804380', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(446, 'G', 'SW03', NULL, NULL, 'Bridgend & District Group', 'Bridgend Ramblers Group organise a variety of regular walks and offer a point of contact on footpath issues which we liaise with local government officers.', 'https://www.bridgendramblers.org', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/bridgend-district-group', '51.546103150000', '-3.590400677419', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(447, 'G', 'SW05', NULL, NULL, 'Vale of Glamorgan Group', 'We\'re a medium sized,active & friendly group. Our walks programme is varied from coast to hills, valleys, and everywhere in between. We walk every Sunday,Wednesday evenings  (summer) &Tuesday(winter)', 'https://www.ramblers.org.uk/vale-of-glamorgan.aspx', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/vale-glamorgan-group', '51.444973710000', '-3.433076840416', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(448, 'G', 'SW06', NULL, NULL, 'Swansea Group', 'Swansea Ramblers have social events & weekly walks of varying lengths.  If you are new to walking, do try one of our regular Saturday short walks or the even shorter strolls listed in our programme.', 'https://www.swansearamblers.org.uk/index.php', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/swansea-group', '51.641605700000', '-4.061195053094', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL);
