(449, 'G', 'SW07', NULL, NULL, 'Cynon Valley', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'cynonvalleyramblers.org.uk', 'https://www.ramblers.org.uk/go-walking/group-finder/areas/glamorgan/groups/cynon-valley.aspx', '51.699554400000', '-3.468514200000', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(450, 'G', 'SW08', NULL, NULL, 'Maesteg Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.maestegramblers.co.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/maesteg-group', '51.596008840000', '-3.641803110138', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(451, 'G', 'SW09', NULL, NULL, 'Merthyr Valley Ramblers', 'The Merthyr Valley Group is based in the Heads of the Valleys area of South Wales.  Our Group Walks mainly take place in and around Merthyr Tydfil, in the Brecon Beacons and elsewhere in South East Wales. Occasionally walks are organised further ...', 'https://www.merthyrramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/merthyr-valley-ramblers', '51.740978170000', '-3.361117220589', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(452, 'G', 'SW11', NULL, NULL, 'Penarth & District Group', 'Penarth & District is a group of about 180 people. We walk most weekends  in the Vale of Glamorgan, Gower, Brecon Beacons, or Wye valley.', 'https://penarthramblers.wordpress.com/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/penarth-district-group', '51.444281290000', '-3.327460936473', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(453, 'G', 'SW12', NULL, NULL, 'Taff Ely Group', 'The Taff Ely Group covers the southern end of Rhondda Cynon Taff.  We provide a range of walks, normally within an hour drive of Llantrisant, and welcome new members.', 'https://www.taffelyramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/taff-ely-group', '51.567105250000', '-3.380277495793', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(454, 'S', 'SW50', NULL, NULL, 'Tiger Bay Ramblers Group', 'Are you young or young at heart? Looking for a friendly walking group that offer a range of walks, social activities, weekends away and holidays to suit all abilities with like minded people? Congratulations, you\'ve just found us!\r\n\r\nWe offer at ...', 'https://www.tigerbayramblers.org.uk/index.php', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/tiger-bay-ramblers-group', '51.572043860000', '-3.381082420659', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(455, 'S', 'SW51', NULL, NULL, 'Tawe Trekkers Group', 'The Tawe Trekkers are a friendly group aimed more towards the working age and young at heart walker in Swansea and the surrounding area. \r\nWe\'re quite a small group but our membership is expanding.', 'https://tawe-trekkers.wixsite.com/tawetrekkers', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/tawe-trekkers-group', '51.637444040000', '-3.829398163693', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(456, 'G', 'GG01', NULL, NULL, 'South Gwent Group', 'Come and let us give you a warm South Gwent Ramblers welcome and share the the marvellous scenery and history of Monmouthshire, the Welsh Valleys and the Brecon Beacons National Park.', 'https://www.ramblers.org.uk/south-gwent', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/south-gwent-group', '51.573671900000', '-2.961898426220', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(457, 'G', 'GG02', NULL, NULL, 'Pontypool Group', 'We walk every weekend,alternating Saturday and Sunday, and on one day during the week.  New walkers are always welcome and you will find Pontypool a friendly Group. Come and enjoy this wonderful area', 'https://www.ramblers.org.uk/pontypool', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/pontypool-group', '51.806652980000', '-2.976912302901', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(458, 'G', 'GG03', NULL, NULL, 'North Gwent Group', 'We are situated on the south side of the Brecon Beacons National Park, within travelling distance of the Black Mountains, Usk and Wye Valleys, Western, Eastern and Rhondda Valleys.', 'https://www.ramblers.org.uk/north-devon', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/north-gwent-group', '51.766749180000', '-3.193859897175', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(459, 'G', 'GG04', NULL, NULL, 'Lower Wye Group', 'Our area is the Lower Wye Valley, extending from Chepstow to Monmouth, an AONB. We also walk in the Royal Forest of Dean, Monmouthshire between the Rivers Usk and the Wye, The Black Mountains and The Brecon Beacons, sometimes further afield. All ...', 'https://www.ramblers.org.uk/lower-wye', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/lower-wye-group', '51.689936980000', '-2.797511106722', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(460, 'G', 'GG05', NULL, NULL, 'Gelligaer Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.ramblersgelligaergroup.co.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/gelligaer-group', '51.649120710000', '-3.234738010391', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(461, 'G', 'GG06', NULL, NULL, 'Islwyn Group', 'Islwyn Ramblers are based in Risca and have a great programme of weekend and midweek walks led by local experts to suit all abilities - from Light \'n Leisurely to the Mountain Goat Division.', 'https://www.islwynramblers.org/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/islwyn-group', '51.661015500000', '-3.150547352422', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(462, 'G', 'LW01', NULL, NULL, 'Clwydian Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.facebook.com/groups/604722516240807/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/clwydian-group', '53.139498650000', '-3.177616729352', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(463, 'G', 'LW02', NULL, NULL, 'Conwy Valley Group', 'Welcome to Conwy Valley Group. Our walks are a great way to find new places, make new friends and enjoy this wonderful area. Click our name for more details', 'https://www.conwyvalleyra.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/conwy-valley-group', '53.140965740000', '-3.736474378736', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(464, 'G', 'LW03', NULL, NULL, 'Ynys Mon Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.ynysmonramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/ynys-mon-group', '53.285727790000', '-4.374398275628', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(465, 'G', 'LW04', NULL, NULL, 'Wrexham Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.wrexhamramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/wrexham-group', '52.990263750000', '-3.017701824823', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(466, 'G', 'LW06', NULL, NULL, 'Meirionnydd Group', 'The Meirionnydd Ramblers are a friendly group of people who enjoy walking, the countryside and the company of other people. We organise regular group walks and are always pleased to welcome newcomers.', 'https://www.meirionnyddramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/meirionnydd-group', '52.809850850000', '-3.852061284101', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(467, 'G', 'LW07', NULL, NULL, 'Berwyn Group', 'Berwyn does hill walking in NE Wales, Cheshire and Shropshire.  Our walks are mainly around 7 to 10 miles, but we also have shorter walks in winter.  Please look up our programme on berwynra.org.uk', 'https://www.berwynra.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/berwyn-group', '52.960405340000', '-3.327222020876', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(468, 'G', 'LW08', NULL, NULL, 'Vale of Clwyd Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.voc-ramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/vale-clwyd-group', '53.153233900000', '-3.375421002259', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(469, 'G', 'LW09', NULL, NULL, 'Deeside Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.deesideramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/deeside-group', '53.259444080000', '-3.183440411698', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(470, 'G', 'LW10', NULL, NULL, 'Eryri Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://eryriramblers.org/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/eryri-group', '52.997610730000', '-4.297792680650', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(471, 'G', 'MW02', NULL, NULL, 'East Radnor Group', 'We are a very friendly Group, covering the Knighton and Presteigne area.\r\nWe have the Offa\'s Dyke Centre, the start of Glyndwr\'s Way and the Heart of Wales Line trail. We walk every week.', 'https://www.ramblers.org.uk/east-radnor', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/east-radnor-group', '52.317628470000', '-3.165468494254', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(472, 'G', 'MW05', NULL, NULL, 'Welshpool Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.ramblers.org.uk/welshpool', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/welshpool-group', '52.644837570000', '-3.403387975978', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(473, 'G', 'MW71', NULL, NULL, 'Four Wells Group', 'We are a small friendly group based in the mid-Wales area bounded by the Spa Towns of Builth, Llandrindod, Llangammarch and Llanwrtyd. Join us for walks in our lovely countryside.', 'https://www.ramblers.org.uk/4-wells', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/four-wells-group', '52.098484970000', '-3.448131289911', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(474, 'G', 'PE01', NULL, NULL, 'Pembrokeshire Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.pembrokeshireramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/pembrokeshire-group', '51.853822760000', '-4.887099977302', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(475, 'G', 'LI12', NULL, NULL, 'Skegness and Horncastle', '', '', '', '0.000000000000', '0.000000000000', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(478, 'G', 'LI13', NULL, NULL, 'Skegness and Horncastle Group', 'We are a small friendly group who welcome newcomers to come along and explore the footpaths and bridleways of the Lincolnshire countryside', 'https://www.ramblers.org.uk/skegness-horncastle', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/skegness-and-horncastle-group', '53.181553110000', '0.038739270790', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(479, 'G', 'DT05', NULL, NULL, 'Bournemouth Happy Monday Ramblers Group', 'We are primarily a social group and our walks end with an optional lunch at a local pub or café.\r\nOur walks start Monday 10:00 (except bank holidays) within one hour\'s drive of Bournemouth', 'https://bournemouthmondayramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/bournemouth-happy-monday-ramblers-group', '50.741835090000', '-1.857879192290', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(555, 'G', 'NS01', 1, 'N', 'East Staffordshire Group', 'We are a friendly group based in East Staffordshire & we enjoy walking throughout the year in all sorts of places & conditions. It\'s a great way of meeting new friends & getting fit & healthy outdoors.', 'https://eaststaffsramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/east-staffordshire-group', '52.863345360000', '-1.812282109465', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(556, 'G', 'NS02', 1, 'N', 'Stone Group', 'We walk in Shropshire, Staffordshire, Cheshire, the Peak District and hold special events in other areas. Please see our website www.stoneramblers.com', 'https://www.stoneramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/stone-group', '52.900148480000', '-2.189013244293', '', 'right', NULL, 'rgba(155, 200, 171, 0.5)', 'rgba(155, 200, 171, 0.1)', 'rgba(155, 200, 171, 1)', '', ''),
(557, 'G', 'NS03', 1, 'N', 'Stoke/Newcastle Group', 'We arrange a range of walking programmes to cater for all ages and abilities. Also social evenings, public transport walks, coach rambles and week-ends away. We welcome new-comers - come and join us!', 'https://www.stokeandnewcastleramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/stokenewcastle-group', '53.000813890000', '-2.271401127102', 'ramblers_logo.png', 'right', 'Sent by Stoke Newcastle Ramblers', 'rgba(155, 200, 171, 0.5)', 'rgba(86, 112, 158, 0.1)', 'rgba(201, 181, 157, 0.4)', 'Welcome to the group', 'Pay up or else'),
(558, 'G', 'NS04', NULL, NULL, 'Tamworth & Lichfield Ramblers', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.tamworthandlichfieldramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/tamworth-lichfield-ramblers', '52.682942880000', '-1.794152071795', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(559, 'G', 'NS05', 1, 'N', 'Mid Staffordshire Group', 'We are a dynamic group based in Mid Staffordshire. We organise regular half and full day walks of various lengths, usually within 50 miles of Stafford but do stray further afield on occasions.', 'https://midstaffsramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/mid-staffordshire-group', '52.796047060000', '-2.157461790811', '', 'right', NULL, 'rgba(155, 200, 171, 0.5)', 'rgba(155, 200, 171, 0.1)', 'rgba(155, 200, 171, 1)', '', ''),
(560, 'G', 'NS06', NULL, NULL, 'Stourbridge Group', '\r\nA friendly and welcoming group of mixed ages. We walk on Tuesdays, Saturdays and Sundays. New members and members from other groups always welcome. ', 'https://stourbridgeramblers.org.uk/', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/stourbridge-group', '52.479769940000', '-2.169225463396', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(561, 'G', 'NS07', NULL, NULL, 'Wolverhampton Group', 'Our groups help local people enjoy walking and protect the places we all love to walk. Most groups organise regular walks led by local experts – a great way to get outside, make new friends and discover how walking boosts your health and happiness.', 'https://www.ramblers.org.uk/wolverhampton', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/wolverhampton-group', '52.599048370000', '-2.170963402660', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
(562, 'G', 'NS08', NULL, NULL, 'Walsall Group', 'The Walsall Group has been around since 1992 and in that time we\'ve introduced many people to the joys and benefits of walking with the Ramblers.\r\n', 'https://walsallramblers.org.uk', 'https://beta.ramblers.org.uk/go-walking/ramblers-groups/walsall-group', '52.599259460000', '-1.966342272456', NULL, 'right', NULL, NULL, '', NULL, NULL, NULL),
